import { alpha, COLORS } from '../config/Colors';
import type { Ball } from '../game/Types';
import { FONT_BIG, FONT_SMALL, TAU } from '../util/Canvas';
import { evFmt, fmt } from '../util/Format';
import { rand } from '../util/MathUtil';
import { BOMB_FUSE } from '../upgrades/Powers';
import { Layer } from './Layer';

/* =====================================================================
   BALLS: trails, glows, and the bomb and electric ball
   ===================================================================== */
export class BallLayer extends Layer {
    drawBalls(a: number, top: number, bot: number): void {
        const ctx = this.ctx, balls = this.game.balls;
        const pos = (b: Ball): [number, number] => { const p = b.body.position; return [b.px + (p.x - b.px) * a, b.py + (p.y - b.py) * a]; };
        ctx.globalCompositeOperation = 'lighter';
        ctx.lineCap = 'round'; ctx.lineJoin = 'round';
        for (const b of balls) {
            const [x, y] = pos(b);
            if (y < top || y > bot) continue;
            const col = b.goo ? COLORS.theme.goo : b.gold ? COLORS.theme.money : b.glow;
            const t = b.trail;
            if (t.length >= 4) {
                ctx.strokeStyle = col; ctx.globalAlpha = 0.35; ctx.lineWidth = b.r * 1.1;
                ctx.beginPath(); ctx.moveTo(t[0], t[1]);
                for (let i = 2; i < t.length; i += 2) ctx.lineTo(t[i], t[i + 1]);
                ctx.lineTo(x, y); ctx.stroke(); ctx.globalAlpha = 1;
            }
            if (b.bomb) {                    // a big red glow that throbs faster as the fuse burns down
                const pulse = 0.5 + 0.5 * Math.sin(b.phase);
                this.r.glow(COLORS.theme.evil, x, y, b.r * (6 + 3 * pulse), 0.75 + 0.25 * pulse);
            } else if (b.zap) {              // a flickering blue glow that grows with the charge
                this.r.glow(COLORS.theme.electric, x, y, b.r * (5 + 3 * b.charge) * rand(0.9, 1.1), 0.8 + 0.2 * b.charge);
            } else this.r.glow(col, x, y, b.r * 5, 0.9);
        }
        ctx.globalCompositeOperation = 'source-over';
        for (const b of balls) {
            const [x, y] = pos(b);
            if (y < top || y > bot) continue;
            ctx.globalAlpha = b.ghost ? 0.5 : 1;  // ghost balls are see-through
            if (b.bomb) { this.drawBomb(b, x, y); continue; }
            if (b.zap) { this.drawZap(b, x, y); continue; }
            ctx.fillStyle = b.goo ? COLORS.theme.goo : b.gold ? COLORS.theme.money : COLORS.ui.strong;
            ctx.beginPath(); ctx.arc(x, y, b.r * 0.78, 0, TAU); ctx.fill();
        }
        ctx.globalAlpha = 1;
    }

    // red bomb with a shine, a ring showing the fuse left, the seconds left and the loot inside
    drawBomb(b: Ball, x: number, y: number): void {
        const ctx = this.ctx, r = b.r, left = Math.max(0, b.fuse) / BOMB_FUSE, secs = Math.ceil(Math.max(0, b.fuse) / 1000);
        const hot = left < 0.3 && Math.sin(b.phase * 2) > 0;   // the last seconds blink white-hot
        ctx.fillStyle = hot ? COLORS.detail.bombHot : COLORS.theme.evil;
        ctx.beginPath(); ctx.arc(x, y, r * 0.85, 0, TAU); ctx.fill();
        ctx.fillStyle = alpha(COLORS.ui.strong, 0.6);
        ctx.beginPath(); ctx.arc(x - r * 0.3, y - r * 0.3, r * 0.22, 0, TAU); ctx.fill();
        ctx.strokeStyle = alpha(COLORS.theme.evil, 0.25); ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(x, y, r + 3.5, 0, TAU); ctx.stroke();
        ctx.strokeStyle = left < 0.3 ? COLORS.ui.strong : COLORS.theme.explosionLight; ctx.lineCap = 'round';
        ctx.beginPath(); ctx.arc(x, y, r + 3.5, -Math.PI / 2, -Math.PI / 2 + TAU * left); ctx.stroke();

        ctx.textAlign = 'center';
        ctx.font = FONT_BIG;
        ctx.fillStyle = hot ? COLORS.ui.strong : COLORS.detail.bombTimer;
        ctx.fillText(String(secs), this.r.onBoard(String(secs), x), y - r - 9);
        const s = b.stash, loot = [s.money && `{money}${fmt(s.money)}`, s.rp && `{research}${fmt(s.rp)}`, s.evil && `{evil}${evFmt(s.evil)}`].filter(Boolean).join('  ');
        if (loot) { ctx.font = FONT_SMALL; ctx.fillStyle = COLORS.theme.money; this.r.richText(loot, x, y - r - 26); }
    }

    // white-hot core, a ring that fills up with the charge, and sparks crackling around it once it is half charged
    drawZap(b: Ball, x: number, y: number): void {
        const ctx = this.ctx, r = b.r;
        ctx.fillStyle = COLORS.theme.electricLight;
        ctx.beginPath(); ctx.arc(x, y, r * 0.8, 0, TAU); ctx.fill();
        ctx.lineWidth = 2.5; ctx.lineCap = 'round';
        ctx.strokeStyle = alpha(COLORS.theme.electric, 0.25);
        ctx.beginPath(); ctx.arc(x, y, r + 3.5, 0, TAU); ctx.stroke();
        ctx.strokeStyle = COLORS.theme.electric;
        ctx.beginPath(); ctx.arc(x, y, r + 3.5, -Math.PI / 2, -Math.PI / 2 + TAU * b.charge); ctx.stroke();
        if (b.charge >= 0.5) {
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = COLORS.theme.electricLight; ctx.lineWidth = 1.2;
            for (let i = 0, n = Math.round(b.charge * 4); i < n; i++) {
                const a = rand(0, TAU), r0 = r + 2, r1 = r + rand(6, 11), m = (r0 + r1) / 2, wob = rand(-0.35, 0.35);
                ctx.beginPath();
                ctx.moveTo(x + Math.cos(a) * r0, y + Math.sin(a) * r0);
                ctx.lineTo(x + Math.cos(a + wob) * m, y + Math.sin(a + wob) * m);
                ctx.lineTo(x + Math.cos(a) * r1, y + Math.sin(a) * r1);
                ctx.stroke();
            }
            ctx.globalCompositeOperation = 'source-over';
        }
    }
}
