import { GRAVITY_SCALE, SWEEP_MARGIN, SWEEP_MS, W } from '../config/World';
import { Effects } from '../engine/Effects';
import { Physics } from '../engine/Physics';
import { evilRegen } from '../upgrades/GooEvilUpgrades';
import { autoInterval, worldHeight } from '../upgrades/MoneyUpgrades';
import { GRAV_MULT } from '../upgrades/Powers';
import { Buckets } from './Buckets';
import { PegBoard } from './PegBoard';
import { Progress } from './Progress';
import { BallSystem } from './systems/BallSystem';
import { BombBall } from './systems/BombBall';
import { Economy } from './systems/Economy';
import { EditMode } from './systems/EditMode';
import { FieldEffects } from './systems/FieldEffects';
import { HitResolver } from './systems/HitResolver';
import { ResearchLab } from './systems/ResearchLab';
import { ZapBall } from './systems/ZapBall';
import { TempEffects } from './TempEffects';
import type { Ball, GameBody, Peg } from './Types';

// an electric arc jump still to land: from one peg to the next, at simT
export type Arc = { from: Peg, to: Peg, at: number, ball: Ball };
// repulsion field in progress: target spacing, and the pairs pushing each other this step (for drawing)
export type Relax = { d0: number, links: Peg[] };

/* =====================================================================
   GAME: owns the state and runs one fixed physics step; the rules are in the systems (game/systems) and peg behaviours (game/pegs)
   ===================================================================== */
export class Game {
    progress: Progress;
    temps: TempEffects;
    effects: Effects;
    balls: Ball[];
    physics: Physics<GameBody>;
    pegs: PegBoard;
    buckets: Buckets;
    worldH: number;
    evilOn: boolean;
    autoOn: boolean;
    simT: number;
    labT: number;
    autoT: number;
    recoil: number;
    launchX: number;
    prevLaunchX: number;
    pendingRemove: Peg[];
    pendingSplit: { ball: Ball, peg: Peg }[];
    uiDirty: boolean;
    relax: Relax | null;
    arcs: Arc[];
    editing: boolean;

    edit: EditMode;
    ballSystem: BallSystem;
    hits: HitResolver;
    economy: Economy;
    bomb: BombBall;
    zap: ZapBall;
    fields: FieldEffects;
    lab: ResearchLab;
    constructor() {
        this.progress = new Progress();
        this.temps = new TempEffects();
        this.effects = new Effects();
        this.balls = [];
        const near: Peg[] = [];
        this.physics = new Physics<GameBody>({
            movers: this.balls,
            staticNear: (x0, y0, x1, y1) => this.pegs.near(x0, y0, x1, y1, near),
            onPairs: pairs => this.hits.contactRules(pairs),
        }, { width: W, gravityScale: GRAVITY_SCALE });
        this.pegs = new PegBoard(this.physics, this.progress);
        this.buckets = new Buckets(this.progress);
        this.physics.onCollisionStart(pairs => this.hits.onContacts(pairs));

        this.worldH = worldHeight(0);
        this.evilOn = false;                 // the Evil toggle (not saved: it always starts off)
        this.autoOn = true;                  // auto dropper switch (the AUTO button, shown once Auto Dropper is researched)
        this.simT = 0;
        this.labT = 0;                       // ms since the research lab's last tick
        this.autoT = 0;
        this.recoil = 0;                     // cannon recoil after a shot, 1 -> 0
        this.launchX = W / 2;                // the cannon sweeps left and right along the ceiling
        this.prevLaunchX = this.launchX;     // launchX before the last physics step (for smooth drawing)
        this.pendingRemove = [];             // pegs and splits are handled after the physics step
        this.pendingSplit = [];
        this.uiDirty = false;                // the UI is refreshed on the next frame (never from inside a physics step)
        this.relax = null;                   // repulsion field in progress: { d0: target spacing, links: pushing pairs }
        this.arcs = [];                      // electric arc jumps still to land: { from, to: peg, at: simT, ball }
        this.editing = false;                // edit mode: the game stands still and pegs can be placed, picked up and moved

        this.edit = new EditMode(this);
        this.ballSystem = new BallSystem(this);
        this.hits = new HitResolver(this);
        this.economy = new Economy(this);
        this.bomb = new BombBall(this);
        this.zap = new ZapBall(this);
        this.fields = new FieldEffects(this);
        this.lab = new ResearchLab(this);
    }

    L(id: string): number { return this.progress.L(id); }
    // the launcher stays near the top; the bucket is anchored to the floor, because the world grows downward
    rimY(): number { return this.worldH - 36; }
    catchY(): number { return this.worldH - 30; }
    // The world grows downward: the launcher and every peg stay where they are, the floor and bucket move down.
    growWorld(): void { this.worldH = worldHeight(this.L('deeper_world')); }

    step(dt: number): void {
        this.simT += dt;
        this.lab.tick(dt);
        this.prevLaunchX = this.launchX;
        this.launchX = W / 2 + (W / 2 - SWEEP_MARGIN) * Math.sin(this.simT * Math.PI * 2 / SWEEP_MS);
        this.recoil = Math.max(0, this.recoil - dt / 220);

        this.temps.tick(dt);
        this.fields.relax();
        this.physics.setGravity(this.temps.running('heavy_gravity') ? GRAV_MULT : 1);
        if (this.temps.running('ghost_balls')) for (const b of this.balls) b.ghost = true;

        const al = this.L('auto_dropper') && 1 + this.L('faster_dropper');   // auto dropper: keeps trying until a ball slot is free
        if (al > 0 && this.autoOn) {
            this.autoT = Math.min(this.autoT + dt, autoInterval(al));
            if (this.autoT >= autoInterval(al) && this.ballSystem.launch()) this.autoT = 0;
        }
        for (const b of this.balls) { b.px = b.body.position.x; b.py = b.body.position.y; }
        this.fields.gravityPegs();
        this.physics.update(dt);
        this.fields.chaos();
        this.ballSystem.update(dt);
        this.zap.updateArcs();

        while (this.pendingSplit.length) { const s = this.pendingSplit.pop()!; this.ballSystem.split(s.ball, s.peg); }
        while (this.pendingRemove.length) {
            const pg = this.pendingRemove.pop()!;
            if (pg.gone) continue;
            pg.gone = true;
            if (pg.evilKill) this.progress.freePegs[pg.type]++;   // broken (by evil or a bomb), not used up: placed again for free
            this.pegs.remove(pg);
        }
        this.buckets.tick(dt);
        this.pegs.tick(dt, this.evilOn ? 0 : evilRegen(this.L('fast_healing')));   // pegs heal while evil is off
        this.effects.tick(dt);
    }
}
