import { COLORS } from '../../config/Colors';
import { mixCol } from '../../util/Canvas';
import { ALCH_MIN, alchMax } from '../../upgrades/MoneyUpgrades';
import type { Ball, Peg } from '../Types';
import { payMoney } from './BasicPeg';
import type { IHitContext, IPegBehavior } from './IPegBehavior';

// pays what it has charged up to (instead of Peg Value), then starts over
export class AlchemyPeg implements IPegBehavior {
    readonly takesGoo = true;
    onHit(ctx: IHitContext, ball: Ball, peg: Peg): void {
        const full = peg.charge >= 1;
        const base = Math.round(ALCH_MIN + (alchMax(ctx.L('alchemy_pegs_value')) - ALCH_MIN) * peg.charge);
        peg.charge = 0; peg.color = COLORS.theme.alchemy;
        payMoney(ctx, ball, peg, base, full ? COLORS.theme.money : mixCol(COLORS.theme.alchemy, COLORS.theme.money, 0.6), full);
    }
}
