import { fmt } from '../../util/Format';
import type { Ball, Peg } from '../Types';
import type { IHitContext, IPegBehavior } from './IPegBehavior';

// a money hit: base value times Peg Power, the combo so far and the gold multiplier
export function payMoney(ctx: IHitContext, ball: Ball, peg: Peg, base: number, col: string, full: boolean): void {
    const v = base * (1 + 0.5 * ctx.L('peg_power')) * (1 + 0.05 * ctx.L('combo_chain') * ball.hits) * ctx.goldMul(ball);
    ball.hits++;
    ctx.earn(ball, 'money', v);
    ctx.fx.burst(peg.x, peg.y, col, full ? 10 : 5);
    ctx.fx.float(peg.x, peg.y - 12, `+{money}${fmt(v)}`, col, { big: full });
}

// pays Peg Value in money (gravity pegs too: their pull is in FieldEffects)
export class BasicPeg implements IPegBehavior {
    readonly takesGoo = true;
    onHit(ctx: IHitContext, ball: Ball, peg: Peg): void { payMoney(ctx, ball, peg, 1 + ctx.L('peg_value'), peg.color, false); }
}
