import { CURRENCIES, type Currency } from '../config/Currencies';
import { colorInk, currencySvg } from '../config/CurrencyIcons';
import { context2d } from '../util/Canvas';

const SIZE = 64;                             // px: sharp at the biggest texts on the board

// the currency icons as images for texts on the board ({money} etc.); each is drawn into its canvas once its SVG has loaded
export function currencyImages(): Record<Currency, HTMLCanvasElement> {
    const out = {} as Record<Currency, HTMLCanvasElement>;
    for (const c of CURRENCIES) {
        const canvas = document.createElement('canvas');
        canvas.width = canvas.height = SIZE;
        const img = new Image();
        img.onload = () => context2d(canvas).drawImage(img, 0, 0, SIZE, SIZE);
        img.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(currencySvg(c, colorInk, SIZE))}`;
        out[c] = canvas;
    }
    return out;
}
