import { PEG_KINDS, PEG_TYPES } from '../upgrades/PegKinds';
import { byId, child, iconHtml, priceHtml, setHtml } from './UiHelpers';
import type { Game } from '../game/Game';
import type { GameRenderer } from '../render/GameRenderer';
import type { PegType } from '../game/Types';

type Chip = { el: HTMLButtonElement, price: HTMLElement };

/* ---------- edit palette: the strip of peg types at the bottom in edit mode, with a description bubble above it ---------- */
export class EditPanel {
    game: Game;
    selected: PegType;
    tipType: PegType | null;
    strip: HTMLElement;
    tip: HTMLElement;
    chips: Partial<Record<PegType, Chip>>;
    constructor(game: Game, renderer: GameRenderer) {
        this.game = game;
        this.selected = 'basic';             // the peg type that a tap on the board places
        this.tipType = null;                 // the type whose description is showing
        this.strip = byId('palStrip');
        this.tip = byId('palTip');
        this.chips = {};
        for (const type of PEG_TYPES) this.chips[type] = this.makeChip(type, renderer);
        // mouse wheel scrolls the strip sideways (a normal wheel only turns vertically)
        this.strip.addEventListener('wheel', e => {
            const strip = this.strip;
            if (strip.scrollWidth <= strip.clientWidth) return;   // everything fits: nothing to scroll
            const d = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
            strip.scrollLeft += e.deltaMode === 1 ? d * 16 : e.deltaMode === 2 ? d * strip.clientWidth : d;   // lines / pages to pixels
            e.preventDefault();
        }, { passive: false });
    }

    makeChip(type: PegType, renderer: GameRenderer): Chip {
        const k = PEG_KINDS[type], el = document.createElement('button');
        el.type = 'button'; el.className = 'chip';
        el.style.setProperty('--k', k.color);
        el.innerHTML = '<canvas width="76" height="76"></canvas><span class="pn"></span><span class="pp"></span>';
        renderer.pegIcon(type, child<HTMLCanvasElement>(el, 'canvas'));
        child(el, '.pn').textContent = k.name;
        let pointer = 'mouse';
        el.addEventListener('pointerdown', e => { pointer = e.pointerType; });
        // mouse: hovering shows the description and a click selects
        el.addEventListener('pointerenter', e => { if (e.pointerType === 'mouse') this.showTip(type); });
        el.addEventListener('pointerleave', e => { if (e.pointerType === 'mouse') this.showTip(null); });
        // touch: a tap selects and shows the description; tapping the selected type again hides it (it stays selected)
        el.addEventListener('click', () => {
            if (pointer === 'mouse') this.selected = type;
            else if (this.selected === type && this.tipType === type) this.showTip(null);
            else { this.selected = type; this.showTip(type); }
            this.refresh();
        });
        this.strip.appendChild(el);
        return { el, price: child(el, '.pp') };
    }

    // a type shows up once it is unlocked
    visible(type: PegType): boolean { return this.game.progress.unlocked(type); }
    priceHtml(type: PegType): string {
        const p = this.game.progress;
        return p.freePegs[type] > 0 ? `${p.freePegs[type]} free` : priceHtml(PEG_KINDS[type].costs);
    }
    showTip(type: PegType | null): void {
        this.tipType = type;
        this.tip.hidden = !type;
        if (!type) return;
        const k = PEG_KINDS[type];
        this.tip.style.setProperty('--k', k.color);
        this.tip.innerHTML = `<b>${k.name} peg</b> · ${this.priceHtml(type)}<br>${iconHtml(k.desc)}`;
    }

    refresh(): void {
        const game = this.game, p = game.progress;
        if (!this.visible(this.selected)) this.selected = 'basic';
        for (const type of PEG_TYPES) {
            const c = this.chips[type], show = this.visible(type);
            if (!c) continue;
            c.el.hidden = !show;
            if (!show) continue;
            setHtml(c.price, this.priceHtml(type));
            c.price.classList.toggle('free', p.freePegs[type] > 0);
            c.el.classList.toggle('sel', type === this.selected);
            c.el.classList.toggle('cant', !!game.edit.cantPlace(type));
        }
    }
}
