import { PEG_KINDS } from '../upgrades/PegKinds';
import { CUR_FIELD, type Costs, entries } from '../config/Currencies';
import type { PegType } from './Types';
import { UPGRADE_BY_ID, UPGRADES } from '../upgrades/Registry';
import { CAP_STEP, START_SLOTS } from '../upgrades/MoneyUpgrades';
import { gooCap } from '../upgrades/GooEvilUpgrades';
import type { Unlockable, Upgrade } from '../upgrades/Types';

/* =====================================================================
   PROGRESS: currencies, upgrade levels and prices
   ===================================================================== */
export class Progress {
    money: number;
    rp: number;
    goo: number;
    evil: number;
    freePegs: Record<PegType, number>;
    levels: Record<string, number>;
    constructor() {
        this.money = 0; this.rp = 0; this.goo = 0; this.evil = 0;   // the balances: this[CUR_FIELD[currency]]
        this.freePegs = { basic: 0, research: 0, splitter: 0, gravity: 0, alchemy: 0, dual: 0 };   // pegs that can be placed without paying (broken ones come back here)
        this.levels = {};
        for (const u of UPGRADES) this.levels[u.id] = 0;
    }
    L(id: string): number { return this.levels[id] | 0; }
    slots(): number { return START_SLOTS + this.L('peg_slots'); }
    unlocked(type: PegType): boolean { const k = PEG_KINDS[type]; return !k.unlock || this.L(k.unlock) > 0; }
    gain(v: number): void { this.money += v; }
    gooCap(): number { return gooCap(this.L('goo_tank')); }
    addGoo(n: number): void { this.goo = Math.min(this.gooCap(), this.goo + n); }

    // { currency: amount } for buying level l + 1; a currency is only charged from its minLevel on
    price(u: Upgrade, l = this.L(u.id)): Costs {
        const out: Costs = {};
        for (const [cur, c] of entries(u.costs)) {
            const from = c.minLevel || 0;
            if (l < from) continue;
            const amount = 'fn' in c ? c.fn(l) : Math.ceil(c.base * (c.growth ?? 1) ** (l - from));
            if (amount > 0) out[cur] = amount;
        }
        return out;
    }
    // costs = { currency: amount }
    has(costs: Costs): boolean { return entries(costs).every(([cur, a]) => this[CUR_FIELD[cur]] >= a); }
    spend(costs: Costs, sign = 1): void { for (const [cur, a] of entries(costs)) this[CUR_FIELD[cur]] -= sign * a; }
    refund(costs: Costs): void { this.spend(costs, -1); }
    canAfford(u: Upgrade): boolean { return this.has(this.price(u)); }
    pay(u: Upgrade): void { this.spend(this.price(u)); }
    // buyable once every required upgrade has its level (anything already owned stays unlocked)
    missing(u: Unlockable) { return (u.required || []).filter(r => this.L(r.id) < (r.level || 1)); }
    isUnlocked(u: Unlockable): boolean { return this.L(u.id) > 0 || !this.missing(u).length; }
    // names only the missing requirements that are discovered themselves (a still-locked one would just be another '???')
    lockReason(u: Unlockable): string {
        const known = this.missing(u).filter(r => this.isUnlocked(UPGRADE_BY_ID[r.id]));
        return known.length ? `Requires: ${known.map(r => UPGRADE_BY_ID[r.id].name + ((r.level || 1) > 1 ? ` Lv ${r.level}` : '')).join(', ')}` : '';
    }
    // money upgrades with a max level get +CAP_STEP per Upgrade Limit level (research + Higher Limit), except the uncapped ones
    maxOf(u: Upgrade): number { return u.max > 0 && u.tab === 'money' && !u.uncapped ? u.max + CAP_STEP * this.L('higher_limit') : u.max; }
    isMaxed(u: Upgrade): boolean { const m = this.maxOf(u); return m > 0 && this.L(u.id) >= m; }
}
