import { alpha, COLORS } from '../config/Colors';
import { context2d, FONT_BIG, FONT_HUGE, FONT_SMALL, glowSprite, TAU } from '../util/Canvas';
import { rand } from '../util/MathUtil';
import type { Camera } from './Camera';
import type { Effects } from './Effects';
import { DPR_TIERS } from './Settings';

// what the renderer draws: the scene's own drawing, with its effects' screen shake and flash around it
// a piece of a text: words, or an icon drawn in its place
export type TextPart = string | { icon: CanvasImageSource };

export interface IScene {
    readonly effects: Effects;
    // a: how far we are between the last two physics steps (0..1); k: world units -> device px; top, bot: visible world rows
    draw(a: number, k: number, top: number, bot: number): void;
}

/* =====================================================================
   RENDERER: canvas, quality tiers and the generic drawing (glows, effects); the scene draws the rest
   ===================================================================== */
export class Renderer {
    canvas: HTMLCanvasElement;
    ctx: CanvasRenderingContext2D;
    camera: Camera;
    worldW: number;
    dpr: number;
    cssW: number;
    tier: number;
    sprites: Record<string, HTMLCanvasElement>;
    icons: Record<string, CanvasImageSource>;
    partCache: Map<string, TextPart[]>;
    ox: number;
    oy: number;
    constructor(canvas: HTMLCanvasElement, camera: Camera, worldW: number) {
        this.canvas = canvas;
        this.ctx = context2d(canvas);
        this.camera = camera;
        this.worldW = worldW;                // the world's width fills the canvas
        this.dpr = 1;
        this.cssW = 360;
        this.tier = navigator.deviceMemory && navigator.deviceMemory <= 4 ? 1 : 0;   // index in DPR_TIERS; low-memory phones (Chrome reports this) start one down
        this.sprites = {};                   // sprite cache for the scene, drawn at device pixels (cleared on resize)
        this.icons = {};                     // name -> image, for {name} inside texts (the scene provides them)
        this.partCache = new Map();
        this.ox = 0; this.oy = 0;            // screen shake offset of the current frame (device px)
    }

    resize(): void {
        const r = this.canvas.getBoundingClientRect();
        this.cssW = r.width;
        this.dpr = Math.min(window.devicePixelRatio || 1, DPR_TIERS[this.tier]);
        this.canvas.width = Math.round(r.width * this.dpr);
        this.canvas.height = Math.round(r.height * this.dpr);
        this.camera.scale = r.width / this.worldW;
        this.camera.viewH = r.height;
        this.sprites = {};
    }
    // one quality tier down (call resize() after); false when already at the lowest
    lowerQuality(): boolean {
        if (this.tier >= DPR_TIERS.length - 1) return false;
        this.tier++;
        return true;
    }

    glow(color: string, x: number, y: number, size: number, alpha: number): void {
        const ctx = this.ctx;
        ctx.globalAlpha = alpha;
        ctx.drawImage(glowSprite(color), x - size / 2, y - size / 2, size, size);
        ctx.globalAlpha = 1;
    }
    // the old shadowBlur glow, faked with a wide faint stroke under the real one (shadowBlur is very slow on phones)
    glowStroke(color: string, width: number, glowW: number, glowA: number): void {
        const ctx = this.ctx;
        ctx.strokeStyle = color;
        ctx.globalAlpha = glowA; ctx.lineWidth = glowW; ctx.stroke();
        ctx.globalAlpha = 1; ctx.lineWidth = width; ctx.stroke();
    }
    // a: how far we are between the last two physics steps (0..1), so moving things are drawn smoothly at any refresh rate
    render(a: number, scene: IScene): void {
        const { ctx, camera } = this, k = this.dpr * camera.scale, shake = scene.effects.shake * this.dpr;
        this.ox = shake ? rand(-shake, shake) : 0;   // screen shake: the whole board is offset (device px)
        this.oy = shake ? rand(-shake, shake) : 0;
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
        this.worldTransform(k);
        const top = camera.y - 40, bot = camera.y + camera.viewH / camera.scale + 40;   // visible world rows, with a margin
        scene.draw(a, k, top, bot);
        this.drawFlash(scene.effects);
    }
    // world units -> device pixels, scrolled by the camera and offset by the screen shake
    worldTransform(k: number): void { this.ctx.setTransform(k, 0, 0, k, this.ox, this.oy - this.camera.y * k); }

    drawFlash(fx: Effects): void {
        const f = fx.flash, ctx = this.ctx;
        if (f.a <= 0) return;
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.globalAlpha = f.a; ctx.fillStyle = f.color;
        ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);
        ctx.globalAlpha = 1;
    }

    // lightning: a fresh jagged path every frame (so it flickers), a wide coloured glow under a thin white core
    drawBolts(fx: Effects): void {
        const ctx = this.ctx, pts: number[] = [];
        ctx.lineCap = 'round'; ctx.lineJoin = 'round';
        for (const bl of fx.bolts) {
            const dx = bl.x2 - bl.x1, dy = bl.y2 - bl.y1, d = Math.hypot(dx, dy) || 1, nx = -dy / d, ny = dx / d;
            const n = Math.max(2, Math.ceil(d / 9)), amp = Math.min(6, d * 0.15), a = bl.life / bl.max;
            pts.length = 0;
            for (let i = 0; i <= n; i++) {
                const t = i / n, off = i === 0 || i === n ? 0 : rand(-amp, amp);
                pts.push(bl.x1 + dx * t + nx * off, bl.y1 + dy * t + ny * off);
            }
            for (const [col, w, alpha] of [[bl.color, 5, 0.4 * a], [COLORS.theme.electricLight, 1.6, a]] as [string, number, number][]) {
                ctx.strokeStyle = col; ctx.lineWidth = w; ctx.globalAlpha = alpha;
                ctx.beginPath(); ctx.moveTo(pts[0], pts[1]);
                for (let i = 2; i < pts.length; i += 2) ctx.lineTo(pts[i], pts[i + 1]);
                ctx.stroke();
            }
        }
        ctx.globalAlpha = 1;
    }

    drawEffects(fx: Effects, top: number, bot: number): void {
        const ctx = this.ctx;
        ctx.globalCompositeOperation = 'lighter';
        this.drawBolts(fx);
        for (const q of fx.particles) {
            if (q.y < top || q.y > bot) continue;
            this.glow(q.color, q.x, q.y, q.size, q.life / q.max);
        }
        for (const g of fx.rings) {          // shockwaves: grow fast, then slow down while fading
            const life = g.life / g.max, rr = g.r0 + (g.r1 - g.r0) * (1 - life ** 3);
            if (g.fill) this.glow(g.color, g.x, g.y, rr * 2, 0.7 * life);
            ctx.globalAlpha = life; ctx.strokeStyle = g.color; ctx.lineWidth = g.width * (0.4 + 0.6 * life);
            ctx.beginPath(); ctx.arc(g.x, g.y, rr, 0, TAU); ctx.stroke();
        }
        ctx.globalAlpha = 1;
        ctx.globalCompositeOperation = 'source-over';

        ctx.textAlign = 'center';
        let lastFont = '';
        for (const f of fx.floaters) {
            if (f.y < top || f.y > bot) continue;
            ctx.globalAlpha = Math.min(1, f.life / f.max * 1.6) * (f.dim ? 0.55 : 1);
            const font = f.huge ? FONT_HUGE : f.big ? FONT_BIG : FONT_SMALL;
            if (font !== lastFont) { ctx.font = lastFont = font; }   // setting ctx.font re-parses the string, so only when it changes
            ctx.fillStyle = f.color;
            this.richText(f.text, f.x, f.y);
        }
        ctx.globalAlpha = 1;
    }

    // x for centred text, moved in so the whole text stays inside the world's width (uses the current font)
    onBoard(text: string, x: number): number {
        const half = this.ctx.measureText(text).width / 2 + 3;
        return Math.min(this.worldW - half, Math.max(half, x));
    }

    // a text split into its words and {name} icons (cached: the same texts come back every frame)
    textParts(text: string): TextPart[] {
        let parts = this.partCache.get(text);
        if (parts) return parts;
        parts = text.split(/\{([a-zA-Z]+)\}/).map((s, i): TextPart => i % 2 && this.icons[s] ? { icon: this.icons[s] } : i % 2 ? `{${s}}` : s).filter(p => p !== '');
        if (this.partCache.size > 400) this.partCache.clear();
        this.partCache.set(text, parts);
        return parts;
    }
    // centred text with {name} icons (from this.icons, at the current font's size), kept inside the world's width;
    // the text takes the current fillStyle, the icons keep their own colours
    richText(text: string, x: number, y: number): void {
        const ctx = this.ctx;
        if (!text.includes('{')) { ctx.textAlign = 'center'; ctx.fillText(text, this.onBoard(text, x), y); return; }
        const parts = this.textParts(text), px = Number(/(\d+(?:\.\d+)?)px/.exec(ctx.font)?.[1] ?? 12), size = px * 1.05, gap = px * 0.1;
        const widths = parts.map(p => typeof p === 'string' ? ctx.measureText(p).width : size + 2 * gap);
        const total = widths.reduce((a, w) => a + w, 0);
        let left = Math.min(this.worldW - 3 - total, Math.max(3, x - total / 2));
        ctx.textAlign = 'left';
        parts.forEach((p, i) => {
            if (typeof p === 'string') ctx.fillText(p, left, y);
            else ctx.drawImage(p.icon, left + gap, y - px * 0.86, size, size);
            left += widths[i];
        });
        ctx.textAlign = 'center';
    }

    // the ?debug readout, in a bar just above the buttons
    drawDebug(text: string): void {
        const ctx = this.ctx, y = this.camera.viewH - this.camera.padBot;
        ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
        ctx.fillStyle = alpha(COLORS.ui.shadow, 0.7); ctx.fillRect(0, y - 18, this.cssW, 18);
        ctx.fillStyle = COLORS.ui.strong; ctx.font = '600 11px system-ui,sans-serif'; ctx.textAlign = 'left';
        ctx.fillText(text, 6, y - 5);
    }
}
