import type { Power } from '../../upgrades/Powers';
import type { Upgrade } from '../../upgrades/Types';
import type { Game } from '../Game';
import type { Timer } from '../TempEffects';

/* =====================================================================
   ECONOMY: buying upgrades and launching powers (prices and balances are in Progress)
   ===================================================================== */
export class Economy {
    game: Game;
    constructor(game: Game) { this.game = game; }

    buy(u: Upgrade): boolean {
        const g = this.game, p = g.progress;
        if (!p.isUnlocked(u) || p.isMaxed(u) || !p.canAfford(u)) return false;
        p.pay(u);
        p.levels[u.id]++;
        if (u.id === 'world_size' || u.id === 'deeper_world') g.growWorld();
        if (u.id === 'blast_peg_hits') for (const pg of g.pegs.list) if (pg.type === 'dual') pg.left++;   // placed blast pegs get the extra hit too
        return true;
    }

    // launches a power: unlocked, not busy (running, recharging or its ball still out), and every cost paid
    usePower(pw: Power): boolean {
        const g = this.game, p = g.progress;
        if (!p.isUnlocked(pw) || this.timer(pw.id) || !p.has(pw.costs)) return false;
        p.spend(pw.costs);
        if (pw.ms) g.temps.start(pw.id); else if (pw.use) pw.use(g);
        g.uiDirty = true;
        return true;
    }
    // a power's state: { active, s } running / recharging, { active, text } for the electric ball's charge; null when ready
    // (the bomb and the electric ball are busy while one is in play)
    timer(id: string): Timer {
        const g = this.game;
        if (id === 'bomb_balls') {
            const b = g.balls.find(b => b.bomb);
            return b ? { active: true, s: Math.max(0, Math.ceil(b.fuse / 1000)) } : null;
        }
        if (id === 'electric_ball') {
            const b = g.balls.find(b => b.zap);
            return b ? { active: true, text: `${Math.round(b.charge * 100)}%` } : null;
        }
        return g.temps.timer(id);
    }
}
