import { COLORS } from '../config/Colors';
import { mixCol } from '../util/Canvas';
import type { Peg } from './Types';

// damaged pegs blend from their own colour towards evil red (damage rounded to 0.1 steps so the sprites stay cached)
export const pegCol = (p: Peg) => p.dmg > 0.02 ? mixCol(p.color, COLORS.theme.evil, Math.round(p.dmg * 10) / 10) : p.color;
