import { BALL_GLOWS } from './Colors';
import { STEP } from '../engine/Settings';

/* =====================================================================
   CONFIG
   ===================================================================== */
export const W = 360;                              // logical world width (height grows with upgrades)
export const PEG_R = 9;
// pegs get slightly smaller the lower they are placed: negligible near the top, up to 15% smaller at a depth of 1500 (about 8 Taller World levels)
export const PEG_SHRINK = 0.15, SHRINK_DEPTH = 1500;
export const pegRadius = (y: number) => PEG_R * (1 - PEG_SHRINK * Math.min(1, (Math.max(0, y) / SHRINK_DEPTH) ** 2));
export const LAUNCH_Y = 38;                        // ball leaves the cannon just below the ceiling
export const BUCKET_X = W / 2;
export const LAUNCH_SPEED = 3;                     // initial downward speed (px per physics step)
export const SWEEP_MS = 3600;                      // time for one full left-right-left sweep
export const SWEEP_MARGIN = 26;                    // how close the cannon gets to the walls
export const MAX_SPEED = 22;
export const BALL_MAX_AGE = 120000;                // ms; only clears a ball that would otherwise bounce around for ever (its haul is lost)
export const GRAVITY_SCALE = 0.0004;
export const G_STEP = GRAVITY_SCALE * STEP * (1000 / 60);          // speed gravity adds per physics step, in Matter's setVelocity units (px per 1/60 s)
export const randGlow = () => BALL_GLOWS[(Math.random() * BALL_GLOWS.length) | 0];

export const LAUNCH_SPREAD = 1;                                     // total random launch range, in degrees
