import { makeSwitch, setSwitch } from './Cards';
import { byId } from './UiHelpers';

// an on/off switch for the game; shown once available
export type Mode = {
    label: string,                           // a few words on what it switches
    color: string,                           // the switch's colour when on
    available: () => boolean,
    on: () => boolean,
    toggle: () => void,
};

type Row = { mode: Mode, el: HTMLDivElement, sw: HTMLButtonElement };

/* =====================================================================
   SETTINGS: a half-height panel of game switches (auto launch, evil, ...), each a short label and an iPhone-style switch,
   and a row that opens the System screen
   ===================================================================== */
export class SettingsView {
    rows: Row[];
    // onSystem: the System row was tapped
    constructor(modes: Mode[], onSystem: () => void) {
        const list = byId('settingsList');
        this.rows = modes.map(mode => {
            const el = this.row(list, mode.label);
            el.style.setProperty('--c', mode.color);
            const sw = makeSwitch(mode.label);
            el.append(sw);
            el.addEventListener('click', () => mode.toggle());   // the whole row switches
            return { mode, el, sw };
        });
        const sys = this.row(list, 'System');
        sys.classList.add('nav');
        const chev = document.createElement('span');
        chev.className = 'chev';
        chev.textContent = '›';
        sys.append(chev);
        sys.addEventListener('click', onSystem);
    }

    // a row with its label, added to list
    row(list: HTMLElement, text: string): HTMLDivElement {
        const el = document.createElement('div');
        el.className = 'mode';
        const label = document.createElement('span');
        label.className = 'label';
        label.textContent = text;
        el.append(label);
        list.appendChild(el);
        return el;
    }

    refresh(): void {
        for (const r of this.rows) {
            const show = r.mode.available(), on = show && r.mode.on();
            r.el.hidden = !show;
            setSwitch(r.sw, on);
        }
    }
}
