import type { Game } from '../game/Game';
import { UPGRADES } from '../upgrades/Registry';
import type { Upgrade } from '../upgrades/Types';
import { LOCKED_SECTION, type Section, SECTION_COLOR, SECTIONS } from '../upgrades/Sections';
import { type Card, makeCard, showLocked } from './Cards';
import { byId, iconHtml, priceHtml, setHtml, setText } from './UiHelpers';

/* =====================================================================
   SHOP / RESEARCH: the upgrade cards of one tab in their own screen; tap to buy, hold to keep buying
   ===================================================================== */
export class ShopView {
    game: Game;
    onChange: () => void;
    list: HTMLElement;
    cards: Card<Upgrade>[];
    order: string | undefined;
    headers: Record<Section | 'locked', HTMLElement>;
    // tab: whose upgrades ('money' or 'research'); listId: the list element; onChange: something was bought (the whole UI refreshes)
    constructor(game: Game, tab: Upgrade['tab'], listId: string, onChange: () => void) {
        this.game = game;
        this.onChange = onChange;
        this.list = byId(listId);
        this.headers = { locked: this.header(LOCKED_SECTION) } as Record<Section | 'locked', HTMLElement>;
        for (const s of SECTIONS) this.headers[s.section] = this.header(s);
        this.cards = UPGRADES.filter(u => u.tab === tab).map(u => this.makeCard(u));
    }

    makeCard(u: Upgrade): Card<Upgrade> {
        const ref = makeCard(u, SECTION_COLOR[u.section]);   // the colour of its section
        // tap to buy; hold to keep buying. (Buying on click, not pointerdown, so scrolling the list never buys.)
        let holdT: number | undefined, holdI: number | undefined, suppress = false;
        const clearHold = () => { clearTimeout(holdT); clearInterval(holdI); holdT = holdI = undefined; };
        ref.btn.addEventListener('pointerdown', () => {
            suppress = false; clearHold();
            holdT = setTimeout(() => {
                suppress = true;
                if (!this.buy(u)) return;
                holdI = setInterval(() => { if (!this.buy(u)) clearHold(); }, 90);
            }, 450);
        });
        for (const ev of ['pointerup', 'pointercancel', 'pointerleave']) ref.btn.addEventListener(ev, clearHold);
        ref.btn.addEventListener('click', () => { if (suppress) { suppress = false; return; } this.buy(u); });
        ref.btn.addEventListener('contextmenu', e => e.preventDefault());
        this.list.appendChild(ref.el);
        return ref;
    }

    // a section's title in the list: small centred text in its colour
    header({ name, color }: { name: string, color: string }): HTMLElement {
        const el = document.createElement('div');
        el.className = 'section';
        el.style.setProperty('--s', color);
        el.textContent = name;
        return el;
    }

    // each section's available cards under its title (in section order), then every locked card under "Locked";
    // a title with no cards under it is hidden
    arrange(): void {
        const groups: [HTMLElement, Card<Upgrade>[]][] = SECTIONS.map(s => [this.headers[s.section], this.cards.filter(c => c.unlocked && c.u.section === s.section)]);
        groups.push([this.headers.locked, this.cards.filter(c => !c.unlocked)]);
        for (const [header, cards] of groups) {
            header.hidden = !cards.length;
            this.list.appendChild(header);
            for (const c of cards) this.list.appendChild(c.el);
        }
    }

    buy(u: Upgrade): boolean {
        if (!this.game.economy.buy(u)) return false;
        this.onChange();
        return true;
    }

    // updates every card; returns whether something can be bought
    refresh(): boolean {
        const p = this.game.progress;
        let order = '', canAfford = false;
        for (const c of this.cards) {
            const u = c.u, unlocked = p.isUnlocked(u), maxed = p.isMaxed(u), l = p.L(u.id);
            c.unlocked = unlocked; order += unlocked ? 1 : 0;
            c.el.classList.toggle('locked', !unlocked);
            if (!unlocked) { showLocked(c, p.lockReason(u)); continue; }
            const once = u.max === 1;                       // bought once (all research): no levels to show, just what it gives
            setText(c.n, u.name);
            setText(c.lvl, once ? (l ? 'OWNED' : '') : maxed ? `Lv ${l} · MAX` : `Lv ${l}`);
            setHtml(c.desc, iconHtml(u.desc));
            setHtml(c.stat, iconHtml(once ? u.stat(1) : maxed ? u.stat(l) : `${u.stat(l)}  →  ${u.stat(l + 1)}`));
            const afford = !maxed && p.canAfford(u);
            if (afford) canAfford = true;
            setText(c.bl, maxed ? (once ? 'OWNED' : 'MAXED') : ''); setHtml(c.bc, maxed ? '✓' : priceHtml(p.price(u)));
            c.btn.classList.toggle('cant', !afford && !maxed);
            c.btn.classList.toggle('maxed', maxed);
        }
        if (order !== this.order) { this.order = order; this.arrange(); }
        return canAfford;
    }
}
