import Matter from 'matter-js';
import type { Point } from '../util/MathUtil';

// the parts of Matter's internals patched below (not in its type definitions)
export type ContactPair<B extends Matter.Body = Matter.Body> = { bodyA: B, bodyB: B, isActive: boolean, isSensor: boolean, restitution: number };
type PairsState<B extends Matter.Body> = { list: ContactPair<B>[] };
type CollisionsHook = { collisions: (detector: { pairs: unknown }) => unknown[], canCollide: (a: Matter.ICollisionFilter, b: Matter.ICollisionFilter) => boolean };
type CollidesHook = { collides: (a: Matter.Body, b: Matter.Body, pairs: unknown) => unknown };
type PairsUpdateHook<B extends Matter.Body> = { update: (pairs: PairsState<B>, collisions: unknown, timestamp: number) => void };

type HasBody<B> = { body: B };

export type PhysicsHooks<B extends Matter.Body> = {
    movers: readonly HasBody<B>[],                                                            // live list: only these are checked for contacts
    staticNear: (x0: number, y0: number, x1: number, y1: number) => readonly HasBody<B>[],   // static bodies that may touch the box
    onPairs: (pairs: ContactPair<B>[]) => void,                                               // contact rules: after Matter sets up its pairs, before it resolves them
};

// width: walls on both sides; gravityScale: Matter's gravity scale at multiplier 1
export type PhysicsOptions = { width: number, gravityScale: number };

/* =====================================================================
   PHYSICS: everything that talks to Matter.js. B: the game's body type (Matter bodies with its own fields)
   ===================================================================== */
export class Physics<B extends Matter.Body = Matter.Body> {
    engine: Matter.Engine;
    world: Matter.World;
    walls: Matter.Body[];
    gravityScale: number;
    constructor(hooks: PhysicsHooks<B>, { width, gravityScale }: PhysicsOptions) {
        const { Engine, Bodies, Composite } = Matter;
        this.engine = Engine.create();
        this.engine.gravity.y = 1;
        this.engine.gravity.scale = this.gravityScale = gravityScale;
        this.world = this.engine.world;
        const o = { isStatic: true, restitution: 0.5, friction: 0, label: 'wall', collisionFilter: { category: 4, mask: 0xFFFFFFFF, group: 0 } };
        this.walls = [
            Bodies.rectangle(-30, 500000, 60, 1000000, o),        // left (very tall: the board has no maximum height)
            Bodies.rectangle(width + 30, 500000, 60, 1000000, o), // right
            Bodies.rectangle(width / 2, -30, width + 200, 60, o), // ceiling
        ];
        Composite.add(this.world, this.walls);
        this.installDetector(hooks);
        this.installContactRules(hooks);
    }

    // Matter's detector sweeps over every body on every step, which gets slow with hundreds of static bodies.
    // Only movers ever collide (movers ignore each other, the rest is static), so check just the movers against nearby static bodies and the walls.
    installDetector({ movers, staticNear }: PhysicsHooks<B>): void {
        const Detector = Matter.Detector as unknown as CollisionsHook, Collision = Matter.Collision as unknown as CollidesHook;
        if (!(Detector && Collision?.collides)) return;
        const walls = this.walls;
        Detector.collisions = (detector) => {
            const out: unknown[] = [], pairs = detector.pairs;
            const test = (A: Matter.Body, B: Matter.Body) => {
                const a = A.bounds, b = B.bounds;
                if (b.min.x > a.max.x || b.max.x < a.min.x || b.min.y > a.max.y || b.max.y < a.min.y) return;
                if (!Detector.canCollide(A.collisionFilter, B.collisionFilter)) return;
                const c = Collision.collides(A, B, pairs);
                if (c) out.push(c);
            };
            for (const m of movers) {
                const A = m.body, a = A.bounds;
                for (const w of walls) test(A, w);
                for (const s of staticNear(a.min.x, a.min.y, a.max.x, a.max.y)) test(A, s.body);
            }
            return out;
        };
    }

    installContactRules({ onPairs }: PhysicsHooks<B>): void {
        const Pairs = Matter.Pairs as unknown as PairsUpdateHook<B>, update = Pairs.update;
        Pairs.update = (pairs, collisions, timestamp) => {
            update(pairs, collisions, timestamp);
            onPairs(pairs.list);
        };
    }

    onCollisionStart(fn: (pairs: ContactPair<B>[]) => void): void {
        Matter.Events.on(this.engine, 'collisionStart', ev => fn(ev.pairs as unknown as ContactPair<B>[]));
    }

    // new bodies are B once the game has attached its own fields
    addPeg(x: number, y: number, r: number, hex: boolean): B {
        const { Bodies, Composite } = Matter;
        const po = { isStatic: true, restitution: 0.5, friction: 0, label: 'peg' };
        const body = hex ? Bodies.polygon(x, y, 6, r + 1, po) : Bodies.circle(x, y, r, po);   // Matter's hexagon has a point at the top, like hexPath()
        Composite.add(this.world, body);
        return body as B;
    }
    // Balls never collide with each other: category 2 is not in their mask (1 = pegs, 4 = walls).
    addBall(x: number, y: number, r: number, vx: number, vy: number, bounce: number): B {
        const body = Matter.Bodies.circle(x, y, r, {
            restitution: bounce, friction: 0, frictionStatic: 0, frictionAir: 0, density: 0.002,
            collisionFilter: { category: 2, mask: 5 }, label: 'ball',
        });
        Matter.Body.setVelocity(body, { x: vx, y: vy });
        Matter.Composite.add(this.world, body);
        return body as B;
    }
    remove(body: Matter.Body): void { Matter.Composite.remove(this.world, body); }
    movePeg(body: Matter.Body, x: number, y: number): void { Matter.Body.setPosition(body, { x, y }); }
    resizePeg(body: Matter.Body, factor: number): void { Matter.Body.scale(body, factor, factor); }

    // velocities in px per 1/60 s, the units setVelocity takes (body.velocity is per 1/90 s physics step)
    velocity(body: Matter.Body): Point { return Matter.Body.getVelocity(body); }
    setVelocity(body: Matter.Body, x: number, y: number): void { Matter.Body.setVelocity(body, { x, y }); }
    setGravity(mult: number): void { this.engine.gravity.scale = this.gravityScale * mult; }
    update(dt: number): void { Matter.Engine.update(this.engine, dt); }
}
