import type { Game } from '../game/Game';
import { type Power, POWERS } from '../upgrades/Powers';
import { type Card, makeCard, showLocked, sortCards } from './Cards';
import { byId, costCol, iconHtml, priceHtml, setHtml, setText } from './UiHelpers';

/* =====================================================================
   POWERS: like the shop's cards, but a tap launches the power (no holding: powers are busy right after)
   ===================================================================== */
export class PowersView {
    game: Game;
    onUsed: () => void;
    list: HTMLElement;
    cards: Card<Power>[];
    order: string | undefined;
    // onUsed: a power was launched
    constructor(game: Game, onUsed: () => void) {
        this.game = game;
        this.onUsed = onUsed;
        this.list = byId('powList');
        this.cards = POWERS.map(pw => this.makeCard(pw));
    }

    makeCard(pw: Power): Card<Power> {
        const ref = makeCard(pw, costCol(pw.costs));   // the colour of what it costs
        ref.btn.addEventListener('click', () => this.use(pw));
        if (pw.danger) ref.btn.classList.add('danger');   // glows red instead of green while running
        if (pw.act) ref.btn.style.setProperty('--act', pw.act);   // or in its own colour
        this.list.appendChild(ref.el);
        return ref;
    }

    use(pw: Power): boolean {
        if (!this.game.economy.usePower(pw)) return false;
        this.onUsed();
        return true;
    }

    // updates every card; returns whether one can be launched right now
    refresh(): boolean {
        const game = this.game, p = game.progress;
        let order = '', canUse = false;
        for (const c of this.cards) {
            const pw = c.u, unlocked = p.isUnlocked(pw);
            c.unlocked = unlocked; order += unlocked ? 1 : 0;
            c.el.classList.toggle('locked', !unlocked);
            if (!unlocked) { showLocked(c, p.lockReason(pw)); continue; }
            setText(c.n, pw.name);
            setText(c.lvl, pw.status ? pw.status() : '');
            setHtml(c.desc, iconHtml(pw.desc));
            setHtml(c.stat, iconHtml(pw.stat()));
            const tm = game.economy.timer(pw.id), ok = !tm && p.has(pw.costs);
            if (ok) canUse = true;
            setText(c.bl, '');
            if (tm) setText(c.bc, tm.text || `${tm.s}s`);   // only the seconds left (or the electric ball's charge)
            else setHtml(c.bc, priceHtml(pw.costs));
            c.btn.classList.toggle('active', !!(tm?.active));      // glowing, twinkling green while running
            c.btn.classList.toggle('cant', !ok && !(tm?.active));
        }
        if (order !== this.order) { this.order = order; sortCards(this.cards, this.list); }
        return canUse;
    }
}
