import type { Unlockable } from '../upgrades/Types';
import { child, setText } from './UiHelpers';

// a shop or power card and the parts of it that refresh() updates
export type Card<T> = {
    u: T, el: HTMLDivElement, n: HTMLElement, lvl: HTMLElement, desc: HTMLElement, stat: HTMLElement,
    btn: HTMLButtonElement, bl: HTMLElement, bc: HTMLElement, unlocked?: boolean,
};

// a card's markup (not in a list yet), in the given colour
export function makeCard<T>(u: T, color: string): Card<T> {
    const el = document.createElement('div');
    el.className = 'card';
    el.style.setProperty('--card', color);   // --card, not --c: the stylesheet mutes a locked card
    el.innerHTML =
        '<div class="info"><div class="name"><span class="n"></span><span class="lvl"></span></div>' +
        '<div class="desc"></div><div class="stat"></div></div>' +
        '<button class="buy" type="button"><span class="bl"></span><span class="bc"></span></button>';
    return {
        u, el,
        n: child(el, '.n'), lvl: child(el, '.lvl'),
        desc: child(el, '.desc'), stat: child(el, '.stat'),
        btn: child<HTMLButtonElement>(el, '.buy'), bl: child(el, '.bl'), bc: child(el, '.bc'),
    };
}

// a locked card: no name, only what unlocks it
export function showLocked(c: Card<unknown>, reason: string): void {
    setText(c.n, '???'); setText(c.lvl, '');
    setText(c.desc, reason);
    setText(c.stat, '');
    setText(c.bl, 'LOCKED'); setText(c.bc, '🔒');
    c.btn.classList.add('cant'); c.btn.classList.remove('maxed');
}

// a settings-style card added to list: name and description on top, a row of buttons below; returns the card and its buttons by id
export function settingRow(list: HTMLElement, color: string, name: string, desc: string, buttons: [string, string, () => void][]): { el: HTMLDivElement, btns: Record<string, HTMLButtonElement> } {
    const el = document.createElement('div');
    el.className = 'card set';
    el.style.setProperty('--card', color);   // --card, not --c: the stylesheet mutes a locked card
    el.innerHTML = `<div class="info"><div class="name">${name}</div><div class="desc">${desc}</div></div><div class="acts"></div>`;
    const acts = child(el, '.acts'), btns: Record<string, HTMLButtonElement> = {};
    for (const [id, label, fn] of buttons) {
        const b = document.createElement('button');
        b.type = 'button'; b.className = 'buy';
        b.innerHTML = `<span class="bc">${label}</span>`;
        b.addEventListener('click', fn);
        acts.appendChild(b);
        btns[id] = b;
    }
    list.appendChild(el);
    return { el, btns };
}

// an iPhone-style on/off switch (filled with the colour in --c when on)
export function makeSwitch(label: string): HTMLButtonElement {
    const sw = document.createElement('button');
    sw.type = 'button'; sw.className = 'switch';
    sw.setAttribute('role', 'switch');
    sw.setAttribute('aria-label', label);
    return sw;
}
export function setSwitch(sw: HTMLButtonElement, on: boolean): void {
    sw.classList.toggle('on', on);
    sw.setAttribute('aria-checked', String(on));
}

// available cards first, then the locked ones, each group in its list order
export function sortCards(cards: Card<Unlockable>[], list: HTMLElement): void {
    for (const c of [...cards.filter(c => c.unlocked), ...cards.filter(c => !c.unlocked)]) list.appendChild(c.el);
}
