import { COLORS } from '../../config/Colors';
import { entries } from '../../config/Currencies';
import { BALL_MAX_AGE, LAUNCH_SPEED, LAUNCH_SPREAD, LAUNCH_Y, MAX_SPEED, randGlow } from '../../config/World';
import { evFmt, fmt } from '../../util/Format';
import { rand } from '../../util/MathUtil';
import { ballRadius, bucketValue, GOLD_CHANCE, goldMult, gooChance, restitution } from '../../upgrades/MoneyUpgrades';
import type { Bucket } from '../Buckets';
import type { Game } from '../Game';
import type { Ball, Peg, Stash } from '../Types';

// reward lines [text, colour] that are not empty (an empty amount leaves a 0 in place of its line)
export const shown = (lines: ([string, string] | number)[]) => lines.filter((l): l is [string, string] => !!l);

/* =====================================================================
   BALLS: launching, splitting, the speed limit, and every way a ball leaves play
   ===================================================================== */
export class BallSystem {
    game: Game;
    constructor(game: Game) { this.game = game; }

    maxBalls(): number { return (1 + this.game.L('extra_ball')) * (this.game.temps.running('ball_burst') ? 10 : 1); }
    load(): number { return this.game.balls.reduce((a, b) => a + b.w, 0); }   // half-size balls count 0.5
    goldMul(b: Ball): number { return b.gold ? goldMult(1 + this.game.L('gold_ball_value')) : 1; }

    /* The cannon hangs from the ceiling and sweeps left and right all the time. It fires straight down
       from wherever it is. Returns false when every ball slot is taken. */
    launch(): boolean {
        const g = this.game;
        if (g.editing || this.load() + 1 > this.maxBalls()) return false;
        const half = LAUNCH_SPREAD * Math.PI / 180 / 2;
        const th = rand(-half, half);                  // 0 = straight down
        const isGoo = Math.random() < (g.L('phlegm_goo') ? gooChance(1 + g.L('more_gooballs')) : 0);
        const isGold = !isGoo && g.L('gold_balls') > 0 && Math.random() < GOLD_CHANCE;   // a ball is never both
        this.make(g.launchX, LAUNCH_Y, ballRadius(g.L('fat_balls')), LAUNCH_SPEED * Math.sin(th), LAUNCH_SPEED * Math.cos(th), { goo: isGoo, gold: isGold });
        g.recoil = 1;
        g.uiDirty = true;
        return true;
    }

    // a ball body plus its game state
    make(x: number, y: number, r: number, vx: number, vy: number, props: Partial<Ball>): Ball {
        const g = this.game, body = g.physics.addBall(x, y, r, vx, vy, restitution(g.L('bouncy_balls')));
        const ball = Object.assign({
            body, r, px: x, py: y, hits: 0, age: 0, still: 0, tick: 0, trail: [], lastPeg: null, lastT: 0,
            goo: false, gold: false, gooHits: 0, expired: false, w: 1, split: false, glow: randGlow(), ghost: g.temps.running('ghost_balls'), inPeg: false,
            chaos: false, bomb: false, fuse: 0, phase: 0, zap: false, charge: 0,
            stash: { money: 0, rp: 0, goo: 0, evil: 0 },   // the haul: paid out in a bucket, lost any other way
        }, props);
        body.ball = ball;
        g.balls.push(ball);
        return ball;
    }
    drop(ball: Ball): void {
        const g = this.game;
        g.physics.remove(ball.body);
        g.balls.splice(g.balls.indexOf(ball), 1);
    }

    /* A full-size ball that hits a splitter peg becomes two half-size balls (deferred until the physics step is over). */
    split(ball: Ball, peg: Peg): void {
        const g = this.game;
        if (g.balls.indexOf(ball) < 0) return;
        const p = ball.body.position, v = g.physics.velocity(ball.body), r = ball.r / 2;
        const base = Math.atan2(v.y, v.x), sp = Math.max(Math.hypot(v.x, v.y), 3);
        this.drop(ball);
        for (const sg of [-1, 1]) {
            const a = base + sg * 0.5;
            this.make(p.x, p.y, r, sp * Math.cos(a), sp * Math.sin(a), {
                hits: ball.hits, age: ball.age, lastPeg: peg, lastT: g.simT, goo: ball.goo, gold: ball.gold, gooHits: ball.gooHits,
                w: 0.5, split: true, glow: ball.glow, ghost: ball.ghost,
                stash: Object.fromEntries(entries(ball.stash).map(([cur, v]) => [cur, v / 2])) as Stash,   // each half carries half the haul
            });
        }
        g.effects.burst(peg.x, peg.y, peg.color, 8);
        g.uiDirty = true;
    }

    // the ball made it: its haul is paid out as is, plus the bucket's own catch value (bucket and gold multipliers apply to that)
    catch(ball: Ball, bk: Bucket, idx: number): void {
        const g = this.game, s = ball.stash, p = g.progress, fx = g.effects, x = ball.body.position.x, y = g.rimY();
        const money = s.money + bucketValue(g.L('bucket_value')) * bk.mult * this.goldMul(ball);
        p.gain(money); p.rp += s.rp; p.addGoo(s.goo); p.evil += s.evil;
        g.buckets.flash[idx] = 1;
        fx.burst(x, y + 4, COLORS.theme.bucket, 10);
        const lines = shown([[`+{money}${fmt(money)}`, COLORS.theme.bucket], s.rp && [`+{research}${fmt(s.rp)}`, COLORS.theme.research],
        s.goo && [`+{goo}${fmt(s.goo)}`, COLORS.theme.goo], s.evil && [`+{evil}${evFmt(s.evil)}`, COLORS.theme.evil]]);
        lines.forEach(([text, col], i) => { fx.float(x, y - 8 - 17 * i, text, col, { big: true, life: 1000, always: true }); });
        this.drop(ball);
    }

    // the ball left play any other way: its haul is gone (a faint red note shows what was lost)
    lose(ball: Ball): void {
        const g = this.game, s = ball.stash, p = ball.body.position;
        const lost = [s.money && `{money}${fmt(s.money)}`, s.rp && `{research}${fmt(s.rp)}`, s.goo && `{goo}${fmt(s.goo)}`, s.evil && `{evil}${evFmt(s.evil)}`].filter(Boolean);
        if (lost.length) g.effects.float(p.x, Math.min(p.y, g.worldH - 12), `−${lost.join(' · ')}`, COLORS.ui.negative, { life: 1000 });
        this.drop(ball);
    }

    // speed limit, trails, and every way a ball leaves play: caught, fallen out, too old, stuck, or a burnt-out gooball
    update(dt: number): void {
        const g = this.game, ph = g.physics, bs = g.buckets.layout(), bomb = g.bomb;
        for (let i = g.balls.length - 1; i >= 0; i--) {
            const b = g.balls[i], p = b.body.position, v = ph.velocity(b.body);
            const sp = Math.hypot(v.x, v.y);
            if (sp > MAX_SPEED) ph.setVelocity(b.body, v.x / sp * MAX_SPEED, v.y / sp * MAX_SPEED);
            b.age += dt;
            b.still = sp < 0.225 ? b.still + dt : 0;          // 0.225 per 1/60 s = 0.15 px per physics step
            // ghost time is over: turn solid only once clear of pegs, or the physics would shove the ball out violently
            if (b.ghost && !g.temps.running('ghost_balls') && !b.inPeg) b.ghost = false;
            if ((++b.tick & 1) === 0) { b.trail.push(p.x, p.y); if (b.trail.length > 14) b.trail.splice(0, 2); }
            if (b.bomb) bomb.burn(b, dt);

            // the bucket is not a physics body: a falling ball whose centre passes the bucket mouth inside its width is caught
            const bi = (v.y > 0 && b.age > 250 && p.y >= g.catchY()) ? g.buckets.indexAt(bs, p.x) : -1;
            if (bi >= 0) {
                if (b.bomb) bomb.cash(b, bs[bi], bi); else this.catch(b, bs[bi], bi);
            } else if (p.y > g.worldH + 40 || b.age > BALL_MAX_AGE || b.still > 1500 || b.expired) {
                if (b.bomb) { bomb.explode(b); continue; }   // a lost bomb goes off where it is
                if (b.expired) g.effects.burst(p.x, p.y, COLORS.theme.goo, 12);
                this.lose(b);
            } else if (b.bomb && b.fuse <= 0) {
                bomb.explode(b);
            }
        }
    }
}
