import { COLORS } from '../config/Colors';

// the groups of the Shop and Research screens, in the order they are shown
export type Section = 'bucket' | 'pegs' | 'balls' | 'research' | 'world' | 'goo' | 'evil';
export const SECTIONS: { section: Section, name: string, color: string }[] = [
    { section: 'bucket', name: 'Bucket', color: COLORS.theme.bucket },
    { section: 'pegs', name: 'Pegs', color: COLORS.theme.pegs },
    { section: 'balls', name: 'Balls', color: COLORS.theme.balls },
    { section: 'research', name: 'Research', color: COLORS.theme.research },
    { section: 'world', name: 'World', color: COLORS.theme.world },
    { section: 'goo', name: 'Goo', color: COLORS.theme.goo },
    { section: 'evil', name: 'Evil', color: COLORS.theme.evil },
];
// section -> its colour (the cards of a section take it too)
export const SECTION_COLOR = Object.fromEntries(SECTIONS.map(s => [s.section, s.color])) as Record<Section, string>;
// locked upgrades are not grouped: they all go last, under this one
export const LOCKED_SECTION = { name: 'Locked', color: COLORS.ui.locked };
