import type { PegType } from '../game/Types';

export const SAVE_KEY = 'neonpegs.save.v2';
export const SAVE_VERSION = 9;

// a save as stored (JSON). Older versions lack fields and a save can be edited by hand, so loading checks every value.
export type SaveData = {
    v: number, money?: number, rp?: number, goo?: number, evil?: number, autoOn?: boolean, labT?: number,
    levels?: Record<string, number>, freePegs?: Record<string, number>,
    timers?: Record<string, unknown>,        // id -> [ms left running, ms of cooldown left]
    pegs?: unknown[],                        // [x, y, type code, hits left, damage, paid, free (1/0)]
    dualReady?: unknown[],                   // before v8: unplaced blast pegs
};

export const SAVE_CODE: Record<PegType, string> = { research: 'r', dual: 'd', splitter: 's', gravity: 'g', alchemy: 'a', basic: 'b' };
export const SAVE_TYPE = Object.fromEntries(Object.entries(SAVE_CODE).map(([type, code]) => [code, type])) as Record<string, PegType>;

// a finite number read from a save, or undefined
export const num = (v: unknown) => typeof v === 'number' && Number.isFinite(v) ? v : undefined;

// a save read from text, or null when the text is not a Neon Pegs save
export function parseSave(text: string): SaveData | null {
    try {
        const d = JSON.parse(text);
        const ok = d && typeof d === 'object' && Number.isFinite(d.v) && d.levels && typeof d.levels === 'object' && Array.isArray(d.pegs);
        return ok ? d : null;
    } catch { return null; }
}
