import type { Effects } from '../engine/Effects';
import type { IScene, Renderer } from '../engine/Renderer';
import type { Game } from '../game/Game';
import type { PegType, View } from '../game/Types';
import { BallLayer } from './BallLayer';
import { BoardLayer } from './BoardLayer';
import { PegLayer } from './PegLayer';

// before the input is wired up: nothing hovered or dragged
const IDLE_VIEW: View = { hover: null, dragging: false, editType: 'basic' };

/* =====================================================================
   GAME DRAWING: the scene, back to front, in layers (board, pegs, balls); the effects come from the engine Renderer
   ===================================================================== */
export class GameRenderer implements IScene {
    r: Renderer;
    game: Game;
    view: View;
    board: BoardLayer;
    pegs: PegLayer;
    balls: BallLayer;
    constructor(r: Renderer, game: Game) {
        this.r = r;
        this.game = game;
        this.view = IDLE_VIEW;               // { hover, dragging, editType } from the input, for the placement preview
        this.board = new BoardLayer(r, game);
        this.pegs = new PegLayer(r, game);
        this.balls = new BallLayer(r, game);
    }
    get effects(): Effects { return this.game.effects; }

    // everything on the board, back to front (the Renderer has cleared the canvas and set the camera)
    draw(a: number, k: number, top: number, bot: number): void {
        const game = this.game;
        this.board.drawBoard(top, bot);
        this.board.drawBucket();
        this.pegs.drawGravityFields(top, bot);
        this.pegs.drawPegs(k, top, bot);
        this.pegs.drawPlacement(this.view);
        this.balls.drawBalls(a, top, bot);
        this.r.drawEffects(game.effects, top, bot);
        if (!game.editing) this.board.drawLauncher(game.prevLaunchX + (game.launchX - game.prevLaunchX) * a, Math.min(game.worldH, bot));   // no cannon while editing
    }

    // a peg picture for the edit palette
    pegIcon(type: PegType, canvas: HTMLCanvasElement): void { this.pegs.pegIcon(type, canvas); }
}
