import { fmt } from '../../util/Format';
import { rpPerHit } from '../../upgrades/MoneyUpgrades';
import type { Ball, Peg } from '../Types';
import type { IHitContext, IPegBehavior } from './IPegBehavior';

// pays research points instead of money
export class ResearchPeg implements IPegBehavior {
    readonly takesGoo = true;
    onHit(ctx: IHitContext, ball: Ball, peg: Peg): void {
        ball.hits++;
        const rp = rpPerHit(ctx.L('research_pegs_value'));
        ctx.earn(ball, 'rp', rp);
        ctx.fx.burst(peg.x, peg.y, peg.color, 6);
        ctx.fx.float(peg.x, peg.y - 12, `+{research}${fmt(rp)}`, peg.color);
    }
}
