import { alpha, COLORS } from '../config/Colors';
import { LAUNCH_Y, W } from '../config/World';
import { TAU } from '../util/Canvas';
import { fmt } from '../util/Format';
import { bucketValue } from '../upgrades/MoneyUpgrades';
import { Layer } from './Layer';

/* =====================================================================
   BOARD: grid, walls, the buckets and the cannon
   ===================================================================== */
export class BoardLayer extends Layer {
    // grid, depth markers, the dimmed outside, walls, ceiling and drain line
    drawBoard(top: number, bot: number): void {
        const ctx = this.ctx, worldH = this.game.worldH;
        const visTop = Math.max(0, top), visBot = Math.min(worldH, bot);   // long lines are only drawn where visible

        // grid, anchored to the top so it stays put when the world grows downward
        ctx.lineWidth = 1 / this.r.camera.scale;
        ctx.strokeStyle = alpha(COLORS.ui.frame, 0.1);
        ctx.beginPath();
        for (let x = 40; x < W; x += 40) { ctx.moveTo(x, visTop); ctx.lineTo(x, visBot); }
        for (let y = 40; y < worldH; y += 40) {
            if (y < top || y > bot) continue;
            ctx.moveTo(0, y); ctx.lineTo(W, y);
        }
        ctx.stroke();

        // depth markers every 200 below the ceiling
        ctx.font = '600 9px system-ui,sans-serif';
        ctx.textAlign = 'left'; ctx.fillStyle = alpha(COLORS.ui.label, 0.55);
        for (let y = 200; y < worldH; y += 200) {
            if (y < top || y > bot) continue;
            ctx.strokeStyle = alpha(COLORS.ui.frame, 0.22);
            ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
            ctx.fillText(String(y), 6, y - 4);
        }

        ctx.fillStyle = alpha(COLORS.ui.page, 0.65);
        ctx.fillRect(-10, worldH, W + 20, 4000);
        ctx.fillRect(-10, -4000, W + 20, 4000);
        ctx.lineCap = 'butt';
        ctx.beginPath(); ctx.moveTo(0, visTop); ctx.lineTo(0, visBot); ctx.moveTo(W, visTop); ctx.lineTo(W, visBot);
        if (top < 0) { ctx.moveTo(0, 0); ctx.lineTo(W, 0); }
        this.r.glowStroke(this.game.editing ? COLORS.ui.boardEditing : COLORS.ui.frame, 2.5, 9, 0.22);   // the board edge turns cyan in edit mode
        if (bot > worldH) {
            ctx.setLineDash([10, 8]);
            ctx.beginPath(); ctx.moveTo(0, worldH); ctx.lineTo(W, worldH);
            this.r.glowStroke(COLORS.ui.drain, 2.5, 9, 0.22);
            ctx.setLineDash([]);
        }
    }

    drawBucket(): void {
        const ctx = this.ctx, game = this.game, bs = game.buckets.layout(), n = bs.length;
        const rim = game.rimY(), bot = game.worldH - 8, base = bucketValue(game.L('bucket_value'));
        for (let i = 0; i < n; i++) {
            const b = bs[i], fl = game.buckets.flash[i];
            const col = n === 1 ? COLORS.theme.bucket : b.t < 0.01 ? COLORS.theme.bucketOuter : b.t > 0.99 ? COLORS.theme.bucket : COLORS.theme.bucketBetween;
            const sl = Math.min(8, b.w * 0.15);
            const x0 = b.cx - b.w / 2, x1 = b.cx + b.w / 2;
            ctx.save();
            ctx.beginPath(); ctx.moveTo(x0, rim); ctx.lineTo(x0 + sl, bot); ctx.lineTo(x1 - sl, bot); ctx.lineTo(x1, rim); ctx.closePath();
            ctx.globalAlpha = 0.08 + 0.3 * fl; ctx.fillStyle = col; ctx.fill();
            ctx.lineJoin = 'round'; ctx.lineCap = 'round';
            ctx.beginPath(); ctx.moveTo(x0, rim); ctx.lineTo(x0 + sl, bot); ctx.lineTo(x1 - sl, bot); ctx.lineTo(x1, rim);
            this.r.glowStroke(col, n > 1 ? 2.5 : 3, 9 + 6 * fl, 0.2 + 0.3 * fl);
            ctx.restore();
            ctx.textAlign = 'center'; ctx.font = `800 ${Math.max(8, Math.min(12, b.w / 3.6))}px system-ui,sans-serif`;
            ctx.fillStyle = col;
            this.r.richText(`{money}${fmt(base * b.mult)}`, b.cx, rim + 17);
        }
    }

    drawLauncher(x: number, visBot: number): void {
        const ctx = this.ctx, y = LAUNCH_Y, recoil = this.game.recoil;

        // faint aim line straight down, so players can time their shot
        ctx.save();
        ctx.strokeStyle = alpha(COLORS.theme.cannon, 0.25); ctx.lineWidth = 1.5; ctx.setLineDash([3, 7]);
        ctx.beginPath(); ctx.moveTo(x, y + 2); ctx.lineTo(x, Math.max(y + 2, visBot)); ctx.stroke();
        ctx.restore();

        ctx.globalCompositeOperation = 'lighter';
        this.r.glow(COLORS.theme.cannon, x, y - 6, 70, 0.45);
        ctx.globalCompositeOperation = 'source-over';

        // barrel, pointing down
        ctx.save();
        ctx.translate(x, 0);
        ctx.fillStyle = COLORS.theme.cannonBody; ctx.strokeStyle = COLORS.theme.cannon; ctx.lineWidth = 2.5;
        ctx.beginPath(); ctx.rect(-6.5, 10 - recoil * 7, 13, 24); ctx.fill(); ctx.stroke();
        ctx.restore();

        // carriage hanging from the ceiling
        ctx.fillStyle = COLORS.theme.cannonBody; ctx.strokeStyle = COLORS.theme.cannon; ctx.lineWidth = 2.5;
        ctx.beginPath(); ctx.rect(x - 15, 0, 30, 14); ctx.fill(); ctx.stroke();
        ctx.beginPath(); ctx.arc(x, 7, 3.5, 0, TAU); ctx.fillStyle = COLORS.theme.cannon; ctx.fill();
    }
}
