import { isCurrency } from '../config/Currencies';
import { GOO_EVIL_UPGRADES } from './GooEvilUpgrades';
import { MONEY_UPGRADES } from './MoneyUpgrades';
import { RESEARCH_UPGRADES } from './ResearchUpgrades';
import { SECTIONS } from './Sections';
import type { Upgrade } from './Types';

/* =====================================================================
   UPGRADES: every upgrade in shop order (data driven: add one with upgrade() in its tab's file and it shows up in the list)
   ===================================================================== */
export const UPGRADES: Upgrade[] = [...MONEY_UPGRADES, ...RESEARCH_UPGRADES, ...GOO_EVIL_UPGRADES];
// the key is the upgrade's id; ids are shared by all tabs, so `required` can point anywhere
export const UPGRADE_BY_ID: Record<string, Upgrade> = Object.fromEntries(UPGRADES.map(u => [u.id, u]));

// mistakes in the definitions: a duplicate id, a missing requirement, no or an unknown currency, no valid tab or section
export function upgradeProblems(list: Upgrade[]): string[] {
    const out: string[] = [], seen = new Set<string>(), byId = Object.fromEntries(list.map(u => [u.id, u]));
    for (const u of list) {
        if (seen.has(u.id)) out.push(`Upgrade "${u.id}" is defined twice`);
        seen.add(u.id);
        for (const r of u.required || []) if (!byId[r.id]) out.push(`Upgrade "${u.id}" requires "${r.id}", which does not exist`);
        if (u.tab !== 'money' && u.tab !== 'research') out.push(`Upgrade "${u.id}" has no valid tab (got "${u.tab}")`);
        if (!SECTIONS.some(s => s.section === u.section)) out.push(`Upgrade "${u.id}" has no valid section (got "${u.section}")`);
        const curs = Object.keys(u.costs || {});
        if (!curs.length) out.push(`Upgrade "${u.id}" has no costs`);
        for (const c of curs) if (!isCurrency(c)) out.push(`Upgrade "${u.id}" costs an unknown currency "${c}"`);
    }
    return out;
}
for (const problem of upgradeProblems(UPGRADES)) console.error(problem);
