/* =====================================================================
   ENGINE SETTINGS
   ===================================================================== */
export const STEP = 1000 / 90;                     // fixed physics step (ms)
export const MAX_STEPS = 3;                        // physics steps per frame; more would make a slow phone even slower (it plays in slow motion instead)
export const DPR_TIERS = [2, 1.5, 1.25, 1];        // quality tiers: the max canvas pixel ratio
export const DEBUG = typeof location !== 'undefined' && /[?&]debug\b/.test(location.search);   // ?debug in the URL shows fps, physics ms, render ms and the pixel ratio
