// player preferences, kept apart from the save (a reset keeps them)
const PREFS_KEY = 'neonpegs.prefs';

export type Prefs = { closeOnPower: boolean, autoFullscreen: boolean };

export function loadPrefs(): Prefs {
    const prefs: Prefs = { closeOnPower: true, autoFullscreen: false };
    try { Object.assign(prefs, JSON.parse(localStorage.getItem(PREFS_KEY) || 'null') || {}); } catch { }
    return prefs;
}
export function savePrefs(prefs: Prefs): void { try { localStorage.setItem(PREFS_KEY, JSON.stringify(prefs)); } catch { } }
