// each ball gets a random bluish or purplish glow
export const BALL_GLOWS = ['#3d8bff', '#4da3ff', '#19a8ff', '#5b7bff', '#7a4dff', '#8a5bff', '#a56bff', '#b78cff'];

// a colour made see-through (for canvas drawing): '#rrggbb' + alpha 0..1 -> 'rgba(r,g,b,a)'
export function alpha(hex: string, a: number): string {
    const n = parseInt(hex.slice(1), 16);
    return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
}

const kebab = (s: string) => s.replace(/[A-Z]/g, c => `-${c.toLowerCase()}`);
// a colour's CSS variable: ('theme', 'moneyRim') -> '--theme-money-rim'
export const cssName = (group: string, name: string) => `--${kebab(group)}-${kebab(name)}`;
// every colour as [CSS variable, value]: COLORS.theme.moneyRim -> ['--theme-money-rim', '#fff3b0']
export const cssColors = (): [string, string][] =>
    Object.entries(COLORS).flatMap(([group, colors]) => Object.entries(colors).map(([name, value]): [string, string] => [cssName(group, name), value]));

// makes every colour available to the CSS as var(--group-name)
export function applyCssColors(root: HTMLElement): void {
    for (const [name, value] of cssColors()) root.style.setProperty(name, value);
}
