import type { Point } from '../util/MathUtil';
import type { Camera } from './Camera';

// what the pointer acts on; T: something on the board that can be dragged
export interface IInputTarget<T> {
    grab(w: Point): T | null;                // pointer down at w: something to drag instead of scrolling
    dragTo(item: T, w: Point): void;
    drop(item: T): void;                     // a drag of item ended
    tap(w: Point): void;
}

// a pointer that is down: where it started, where it is, and what it is dragging (if anything)
type Drag<T> = { id: number, x0: number, y0: number, cam0: number, lastX: number, lastY: number, lastT: number, moved: boolean, item: T | null };

/* =====================================================================
   INPUT: drag to scroll (with momentum), the mouse wheel, taps, and dragging what the target grabs
   ===================================================================== */
export class Input<T> {
    canvas: HTMLCanvasElement;
    camera: Camera;
    target: IInputTarget<T>;
    drag: Drag<T> | null;
    hover: Point | null;
    constructor(canvas: HTMLCanvasElement, camera: Camera, target: IInputTarget<T>) {
        this.canvas = canvas;
        this.camera = camera;
        this.target = target;
        this.drag = null;
        this.hover = null;                   // mouse position in the world (for the placement preview)

        canvas.addEventListener('pointerdown', e => {
            canvas.setPointerCapture(e.pointerId);
            const item = target.grab(this.toWorld(e.clientX, e.clientY));
            this.drag = { id: e.pointerId, x0: e.clientX, y0: e.clientY, cam0: camera.y, lastX: e.clientX, lastY: e.clientY, lastT: performance.now(), moved: false, item };
            camera.vel = 0;
        });
        canvas.addEventListener('pointermove', e => this.move(e));
        canvas.addEventListener('pointerup', e => this.end(e, false));
        canvas.addEventListener('pointercancel', e => this.end(e, true));
        canvas.addEventListener('pointerleave', e => { if (e.pointerType === 'mouse') this.hover = null; });
        // mouse wheel scrolls the board (the open shop covers the canvas, so there the wheel scrolls the shop list instead)
        canvas.addEventListener('wheel', e => {
            e.preventDefault();
            const px = e.deltaMode === 1 ? e.deltaY * 16 : e.deltaMode === 2 ? e.deltaY * camera.viewH : e.deltaY;   // lines / pages to pixels
            camera.vel = 0;
            camera.y += px / camera.scale;
            camera.clamp();
            this.hover = this.toWorld(e.clientX, e.clientY);   // keep the placement preview under the mouse
        }, { passive: false });
    }
    get dragging(): boolean { return !!this.drag; }

    toWorld(cx: number, cy: number): Point {
        const r = this.canvas.getBoundingClientRect();
        return { x: (cx - r.left) / this.camera.scale, y: (cy - r.top) / this.camera.scale + this.camera.y };
    }

    move(e: PointerEvent): void {
        const drag = this.drag, cam = this.camera;
        if (e.pointerType === 'mouse') this.hover = this.toWorld(e.clientX, e.clientY);
        if (!drag || e.pointerId !== drag.id) return;
        const dx = e.clientX - drag.x0, dy = e.clientY - drag.y0;
        if (!drag.moved && Math.hypot(dx, dy) > 8) drag.moved = true;
        if (!drag.moved) return;
        if (drag.item) {                     // dragging an item: it follows the pointer
            drag.lastX = e.clientX; drag.lastY = e.clientY;
            this.target.dragTo(drag.item, this.toWorld(e.clientX, e.clientY));
            return;
        }
        cam.y = drag.cam0 - dy / cam.scale;
        cam.clamp();
        const now = performance.now(), dt = now - drag.lastT;
        if (dt > 0) {
            const v = (drag.lastY - e.clientY) / cam.scale / dt * 1000;
            cam.vel = cam.vel * 0.5 + v * 0.5;
        }
        drag.lastY = e.clientY; drag.lastT = now;
    }
    end(e: PointerEvent, cancelled: boolean): void {
        const d = this.drag;
        if (!d || e.pointerId !== d.id) return;
        this.drag = null;
        if (d.item && d.moved) { this.target.drop(d.item); return; }
        if (cancelled) return;
        if (!d.moved) { this.camera.vel = 0; this.target.tap(this.toWorld(e.clientX, e.clientY)); }
        else if (performance.now() - d.lastT > 90) this.camera.vel = 0;
    }

    // while an item is dragged near the top or bottom of the visible board, the board scrolls along
    update(dt: number): void {
        const d = this.drag;
        if (!d?.item || !d.moved) return;
        const cam = this.camera, y = d.lastY - this.canvas.getBoundingClientRect().top, edge = 48;
        const dir = y < cam.padTop + edge ? -1 : y > cam.viewH - cam.padBot - edge ? 1 : 0;
        if (!dir) return;
        cam.y += dir * 420 / cam.scale * dt / 1000;
        cam.clamp();
        this.target.dragTo(d.item, this.toWorld(d.lastX, d.lastY));
    }
}
