export const TAU = Math.PI * 2;
export const FONT_BIG = '800 15px system-ui,sans-serif', FONT_SMALL = '700 11px system-ui,sans-serif', FONT_HUGE = '900 24px system-ui,sans-serif';

// blend two #rrggbb colours (t = 0..1); cached, since the same few blends are asked for every frame
export const mixCache: Record<string, string> = {};
export function mixCol(a: string, b: string, t: number): string {
    const k = a + b + t;
    if (mixCache[k]) return mixCache[k];
    const pa = parseInt(a.slice(1), 16), pb = parseInt(b.slice(1), 16);
    const ch = (s: number) => Math.round(((pa >> s) & 255) * (1 - t) + ((pb >> s) & 255) * t);
    return (mixCache[k] = `#${((1 << 24) | (ch(16) << 16) | (ch(8) << 8) | ch(0)).toString(16).slice(1)}`);
}

export const glowCache: Record<string, HTMLCanvasElement> = {};
export function glowSprite(color: string): HTMLCanvasElement {
    if (glowCache[color]) return glowCache[color];
    const c = document.createElement('canvas'); c.width = c.height = 64;
    const g = context2d(c);
    const gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
    gr.addColorStop(0, `${color}ff`); gr.addColorStop(0.35, `${color}77`); gr.addColorStop(1, `${color}00`);
    g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
    return (glowCache[color] = c);
}
// a hexagon with a point at the top and bottom and flat sides
export function hexPath(g: CanvasRenderingContext2D, x: number, y: number, r: number): void {
    g.beginPath();
    for (let i = 0; i < 6; i++) {
        const a = i * Math.PI / 3 + Math.PI / 6, px = x + r * Math.cos(a), py = y + r * Math.sin(a);
        if (i) g.lineTo(px, py); else g.moveTo(px, py);
    }
    g.closePath();
}
// a canvas's 2D context (only null when the canvas already has another kind of context, which never happens here)
export function context2d(c: HTMLCanvasElement): CanvasRenderingContext2D {
    const g = c.getContext('2d');
    if (!g) throw new Error('2D canvas not available');
    return g;
}
