import { COLORS } from '../config/Colors';
import { type Costs, isCurrency } from '../config/Currencies';
import type { PegType } from '../game/Types';
import { ALCH_MIN, ALCH_MS, alchMax, DUAL_HITS, DUAL_MULT } from './MoneyUpgrades';

/* ---- peg types: placed in edit mode. Each takes a peg slot and costs a flat price to place: costs = { currency: amount } (all are taken).
        unlock = the research upgrade that makes the type available (none: available from the start). ---- */
export type PegKind = { name: string, color: string, costs: Costs, unlock?: string, desc: string };
export const PEG_KINDS: Record<PegType, PegKind> = {
    basic: { name: 'Peg', color: COLORS.theme.pegs, costs: { money: 10 }, desc: 'Every hit adds more money.' },
    research: { name: 'Research', color: COLORS.theme.research, costs: { money: 150 }, unlock: 'research_pegs', desc: 'Every hit adds research points.' },
    splitter: { name: 'Splitter', color: COLORS.theme.splitter, costs: { money: 400 }, unlock: 'splitter_pegs', desc: 'Splits balls in half.' },
    gravity: { name: 'Gravity', color: COLORS.theme.gravity, costs: { money: 600 }, unlock: 'gravity_pegs', desc: `Pulls balls towards it.` },
    alchemy: { name: 'Alchemy', color: COLORS.theme.alchemy, costs: { money: 500 }, unlock: 'alchemy', desc: `Slowly turns to gold: from {money}${ALCH_MIN} to {money}${alchMax(0)} in ${ALCH_MS / 1000}s. A hit pays it out and starts it over.` },
    dual: { name: 'Blast', color: COLORS.theme.money, costs: { money: 1000 }, unlock: 'blast_pegs', desc: `Pays money AND research points at x${DUAL_MULT} for ${DUAL_HITS} hits (more with Blast Peg Hits), then it is used up.` },
};
export const PEG_TYPES = Object.keys(PEG_KINDS) as PegType[];
for (const t of PEG_TYPES) for (const c in PEG_KINDS[t].costs) if (!isCurrency(c)) console.error(`Peg type "${t}" costs an unknown currency "${c}"`);
