import type { Currency } from '../config/Currencies';
import type { Section } from './Sections';

// price of one level: base * growth^(level - minLevel), or fn(level); charged from minLevel on
export type Cost = { base: number, growth?: number, minLevel?: number } | { fn: (l: number) => number, minLevel?: number };
// that upgrade's own level must be at least `level` (1 when left out)
export type Requirement = { id: string, level?: number };
// what Progress needs to tell whether an upgrade or power is unlocked
export type Unlockable = { id: string, name: string, required?: Requirement[] };
export type Upgrade = Unlockable & {
    tab: 'money' | 'research', section: Section, max: number, uncapped?: boolean,
    costs: Partial<Record<Currency, Cost>>, desc: string, stat: (l: number) => string
};

// returns upgrade(id, definition), which appends to `list` (the shop shows each list in the order it was filled)
export const defineIn = (list: Upgrade[]) => (id: string, u: Omit<Upgrade, 'id'>) => { list.push({ id, ...u }); };
