import type { Ball, Peg } from '../Types';
import { BasicPeg } from './BasicPeg';
import type { IHitContext } from './IPegBehavior';

// splits a full-size ball in two half-size balls (once per ball), and pays like a basic peg
export class SplitterPeg extends BasicPeg {
    onHit(ctx: IHitContext, ball: Ball, peg: Peg): void {
        if (ball.w === 1 && !ball.split) { ball.split = true; ctx.queueSplit(ball, peg); }
        super.onHit(ctx, ball, peg);
    }
}
