import { COLORS, cssName } from './Colors';
import type { Currency } from './Currencies';

/* =====================================================================
   CURRENCY ICONS: the coin, hexagon, drop and star, drawn the same way everywhere: the HUD, prices and texts on the page,
   and texts on the board (as images). Inside a text an icon is written as {money}, {research}, {goo} or {evil}.
   ===================================================================== */
type ThemeColor = keyof typeof COLORS.theme;
// how a shape gets its colours: a CSS variable on the page (follows the palette), the colour itself inside an image
export type Ink = (name: ThemeColor) => string;
export const cssInk: Ink = name => `var(${cssName('theme', name)})`;
export const colorInk: Ink = name => COLORS.theme[name];

const SHAPES: Record<Currency, (ink: Ink) => string> = {
    money: ink => `<circle cx="12" cy="12" r="9.5" style="fill:${ink('money')};stroke:${ink('moneyRim')};stroke-width:1.6"/>`
        + `<circle cx="12" cy="12" r="5.6" style="fill:none;stroke:${ink('moneyRing')};stroke-width:1.8"/>`,
    research: ink => `<polygon points="12,2 21,7 21,17 12,22 3,17 3,7" style="fill:${ink('research')};fill-opacity:.25;stroke:${ink('research')};stroke-width:2.2;stroke-linejoin:round"/>`,
    goo: ink => `<path d="M12 2.5C12 2.5 5.5 10 5.5 15a6.5 6.5 0 0 0 13 0C18.5 10 12 2.5 12 2.5Z" style="fill:${ink('goo')};fill-opacity:.3;stroke:${ink('goo')};stroke-width:2.2;stroke-linejoin:round"/>`,
    evil: ink => `<polygon points="12,2.5 14.4,9.3 21.5,9.4 15.8,13.7 17.9,20.6 12,16.5 6.1,20.6 8.2,13.7 2.5,9.4 9.6,9.3" style="fill:${ink('evil')};fill-opacity:.3;stroke:${ink('evil')};stroke-width:2;stroke-linejoin:round"/>`,
};

// a currency's icon as SVG markup; size: for an image (an <svg> on the page is sized by the CSS)
export function currencySvg(c: Currency, ink: Ink, size?: number): string {
    const dims = size ? ` width="${size}" height="${size}"` : '';
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"${dims}>${SHAPES[c](ink)}</svg>`;
}
