/* =====================================================================
   FULLSCREEN: the browser's fullscreen API (and Safari's prefixed one), plus auto fullscreen:
   while it is on, any tap or click goes back into fullscreen
   ===================================================================== */
export class Fullscreen {
    supported: boolean;
    on: boolean;                             // cached, kept up to date by the browser's events: a tap reads no DOM
    pending: boolean;                        // a request is under way (no second one meanwhile)
    skip: Element | null;                    // taps on this do not count (the auto fullscreen switch itself)
    // auto: whether auto fullscreen is switched on
    constructor(auto: () => boolean) {
        const doc = document;
        this.supported = !!(doc.fullscreenEnabled || doc.webkitFullscreenEnabled);
        this.on = !!(doc.fullscreenElement || doc.webkitFullscreenElement);
        this.pending = false;
        this.skip = null;
        const sync = () => { this.on = !!(doc.fullscreenElement || doc.webkitFullscreenElement); };
        doc.addEventListener('fullscreenchange', sync);
        doc.addEventListener('webkitfullscreenchange', sync);
        // pointerup, not pointerdown: browsers only allow fullscreen from a finished tap or click
        if (this.supported) doc.addEventListener('pointerup', e => {
            if (!this.on && !this.pending && auto() && !this.skip?.contains(e.target as Node)) this.enter();
        }, { capture: true, passive: true });
    }

    // asks for fullscreen (from a tap or click); a refusal is silent, the next tap simply tries again
    enter(): void {
        const el = document.documentElement, request = el.requestFullscreen || el.webkitRequestFullscreen;
        if (!this.supported || this.on || !request) return;
        this.pending = true;
        const done = () => { this.pending = false; };
        const p = request.call(el);
        if (p?.then) p.then(done, done); else done();   // old Safari returns nothing
    }
}
