import { type Costs, type Currency, CURRENCIES, entries, RES_COL } from '../config/Currencies';
import { cssInk, currencySvg } from '../config/CurrencyIcons';
import { fmt } from '../util/Format';

// an element the page must have (a missing one is a bug in index.html)
export function byId<T extends HTMLElement = HTMLElement>(id: string): T {
    const el = document.getElementById(id);
    if (!el) throw new Error(`#${id} is missing from the page`);
    return el as T;
}
// a child element that a template is known to contain
export function child<T extends Element = HTMLElement>(root: ParentNode, selector: string): T {
    const el = root.querySelector<T>(selector);
    if (!el) throw new Error(`${selector} is missing`);
    return el;
}

// the screens that slide up over the board (one at a time): name -> element id
export type Screen = 'shop' | 'research' | 'powers' | 'settings' | 'system';
export const SCREENS: Record<Screen, string> = { shop: 'overlay', research: 'research', powers: 'powers', settings: 'settings', system: 'system' };
// a card takes the colour of the first currency it costs
export const costCol = (costs: Partial<Record<Currency, unknown>>) => RES_COL[Object.keys(costs)[0] as Currency] || RES_COL.money;
// text and HTML are only written when they change (writing them is slow, and these are refreshed often); _t keeps the last value
type Cached = Element & { _t?: string };
export const setText = (node: Cached, s: string) => { if (node._t !== s) { node._t = s; node.textContent = s; } };
export const setHtml = (node: Cached, s: string) => { if (node._t !== s) { node._t = s; node.innerHTML = s; } };
// the currency icons (the same as on the board), coloured from the palette
export const CUR_ICON = Object.fromEntries(CURRENCIES.map(c => [c, currencySvg(c, cssInk)])) as Record<Currency, string>;
// a text with {money}-style icons -> HTML with the icons (the texts are the game's own: nothing to escape)
export const iconHtml = (text: string) => text.replace(/\{(money|research|goo|evil)\}/g, (_, c: Currency) => `<span class="ic">${CUR_ICON[c]}</span>`);
export const priceHtml = (price: Costs) => entries(price).map(([cur, a]) => `<span class="pc">${CUR_ICON[cur]}${fmt(a)}</span>`).join('') || 'FREE';
