import type { Renderer } from '../engine/Renderer';
import type { Game } from '../game/Game';

// a part of the game drawing: draws with the renderer's canvas and helpers, reads the game
export class Layer {
    r: Renderer;
    game: Game;
    constructor(r: Renderer, game: Game) {
        this.r = r;
        this.game = game;
    }
    get ctx(): CanvasRenderingContext2D { return this.r.ctx; }
}
