/* =====================================================================
   HELPERS
   ===================================================================== */
export const SUF = ['', 'K', 'M', 'B', 'T', 'Qa', 'Qi', 'Sx', 'Sp', 'Oc', 'No', 'Dc'];
export function fmt(n: number): string {
    if (!Number.isFinite(n)) return '∞';
    if (n < 1000) return (n >= 100 || Math.abs(n - Math.round(n)) < 0.05) ? String(Math.round(n)) : n.toFixed(1);
    const e = Math.floor(Math.log10(n) / 3);
    if (e >= SUF.length) return n.toExponential(2);
    const v = n / 1000 ** e;
    return (v < 10 ? v.toFixed(2) : v < 100 ? v.toFixed(1) : v.toFixed(0)) + SUF[e];
}

export const secs = (ms: number) => `${(ms / 1000).toFixed(ms < 1000 ? 2 : 1)}s`;

/* =====================================================================
   HELPERS
   ===================================================================== */
// evil comes in small amounts (0.01 per hit), so show two decimals until it gets big
export const evFmt = (n: number) => n < 100 ? n.toFixed(2) : fmt(n);
