    bucket: 'bucket_value',
    peg: 'peg_slots',
    balls: 'extra_ball',
    power: 'peg_power',
    wide: 'wide_bucket',
    research: 'research_lab',
    rpeg_value: 'research_pegs_value',
    combo: 'combo_chain',
    bounce: 'bouncy_balls',
    fat: 'fat_balls',
    deeper: 'deeper_world',
    dropper: 'faster_dropper',
    bucketrow: 'extra_buckets',
    goldvalue: 'gold_ball_value',
    gooball: 'more_gooballs',
    goolife: 'lasting_goo',
    goopay: 'rich_phlegm',
    capx: 'higher_limit',
    rpeg: 'research_pegs',
    depth: 'world_size',
    cap: 'upgrade_limit',
    auto: 'auto_dropper',
    rcombo: 'combo_theory',
    rgold: 'alchemy',
    rbounce: 'elastic_balls',
    rfat: 'ball_inflation',
    splitpeg: 'splitter_pegs',
    gravpeg: 'gravity_pegs',
    goldball: 'gold_balls',
    buckets: 'more_buckets',
