// before v3 there was no edit mode
export const isPreEditMode = (d: SaveData): boolean => (d.v | 0) < 3;

// copies levels and timers saved under an old id to the new id (an entry already under the new id wins)
export function applyRenames(d: SaveData): void {
    for (const o of [d.levels, d.timers] as (Record<string, unknown> | undefined)[]) if (o) for (const old in RENAMED) if (o[old] !== undefined && o[RENAMED[old]] === undefined) o[RENAMED[old]] = o[old];
}

// Saves from before edit mode: every peg was bought one by one, then placed for free. Now there are slots and pegs cost
// money to place. So everything owned becomes a slot, owning a special peg unlocks its type, unplaced pegs become free
// placements, and placed pegs count as paid for (picking one up refunds its price).
export function migrateEditMode(d: SaveData, p: Progress): void {
    const lv = d.levels || {};
    const owned = { basic: lv.peg_slots | 0, research: lv.research_pegs | 0, splitter: lv.splitter_pegs | 0, gravity: lv.gravity_pegs | 0 };
    const placed: Record<PegType, number> = { basic: 0, research: 0, splitter: 0, gravity: 0, alchemy: 0, dual: 0 };
    for (const pt of Array.isArray(d.pegs) ? d.pegs : []) if (Array.isArray(pt) && pt[2] !== 'd') placed[SAVE_TYPE[pt[2]] || 'basic']++;
    let total = 0;
    for (const t of Object.keys(owned) as (keyof typeof owned)[]) {
        total += Math.max(owned[t], placed[t]);
        p.freePegs[t] = Math.max(0, owned[t] - placed[t]);
    }
    p.levels.peg_slots = Math.max(0, total - START_SLOTS);
    for (const id of ['research_pegs', 'splitter_pegs', 'gravity_pegs']) p.levels[id] = Math.min(1, p.levels[id]);
}

// level changes between versions, applied to levels already loaded into p
export function migrateLevels(d: SaveData, p: Progress): void {
    const v = d.v | 0;
    // before v4 research could have many levels; now it is bought once (the extra levels are gone, money upgrades take over)
    if (v < 4) for (const u of UPGRADES) if (u.tab === 'research') p.levels[u.id] = Math.min(1, p.levels[u.id]);
    // before v5 these money upgrades had no research: owned levels keep their effect, the research now counting as the first one
    if (v < 5) for (const [r, m] of [['combo_theory', 'combo_chain'], ['elastic_balls', 'bouncy_balls'], ['ball_inflation', 'fat_balls']]) if (p.levels[m] > 0) { p.levels[r] = 1; p.levels[m]--; }
    // before v7 these research upgrades also gave the first level of their money upgrade (now they only unlock it)
    if (v < 7) for (const [r, m] of [['combo_theory', 'combo_chain'], ['elastic_balls', 'bouncy_balls'], ['ball_inflation', 'fat_balls'], ['world_size', 'deeper_world'], ['more_buckets', 'extra_buckets'], ['upgrade_limit', 'higher_limit']]) if (p.levels[r] > 0) p.levels[m]++;
    // before v8 blast pegs were bought in the Goo tab and waited unplaced (d.dualReady): those become free blast pegs,
    // and anyone who had blast pegs gets the new Blast Pegs research
    const ready = Array.isArray(d.dualReady) ? d.dualReady.filter(n => (n as number) > 0).length : 0;
    p.freePegs.dual += ready;
    if (v < 8 && (ready || (d.pegs || []).some(pt => Array.isArray(pt) && pt[2] === 'd'))) p.levels.blast_pegs = 1;
}
