/* ---- bomb balls: a red ball that keeps everything it earns; it pays x10 in a bucket, or explodes when its fuse runs out ---- */
export const BOMB_COSTS: Costs = { evil: 40, goo: 150 };            // fixed price
export const BOMB_FUSE = 10000;                                     // ms until it explodes
export const BOMB_MULT = 10;                                        // payout multiplier when it lands in a bucket
export const BOMB_R = 70;                                           // pegs within this distance break when it explodes
export const BOMB_EVIL_BASE = 5, BOMB_EVIL_PEG = 10;                // evil from an explosion: base + per broken peg (times Dark Harvest)
power('bomb_balls', {
    required: [{ id: 'evil' }], danger: true, name: 'Bomb Balls',
    costs: BOMB_COSTS,
    desc: `Fires a red bomb ball (it does not count towards your ball limit). If it lands in a bucket it pays out x${BOMB_MULT} of everything it collected. If its ${BOMB_FUSE / 1000}s fuse runs out first, or it is lost, it explodes: the loot is gone, pegs nearby break and must be placed again, and you get Evil instead.`,
    status: () => 'one at a time',
    stat: () => `${BOMB_FUSE / 1000}s fuse, x${BOMB_MULT} payout in a bucket`,
    use: game => game.bomb.launch()
});

// repulsion field (evil): pegs that are too close push each other apart for a few seconds, evening out the gaps
export const RELAX_MS = 5000, RELAX_CD = 30000;                     // duration, cooldown
export const RELAX_MOVE = 1.2;                                      // fastest a peg moves (px per physics step)
power('repulsion_field', {
    required: [{ id: 'evil' }], danger: true, name: 'Repulsion Field', ms: RELAX_MS, cd: RELAX_CD,
    costs: { evil: 30, goo: 120 },
    desc: `For ${RELAX_MS / 1000} seconds every peg pushes away the pegs that are too close to it (the walls push back too), so crowded spots spread out and the gaps between pegs even out. Pegs keep their new places. Then it needs ${RELAX_CD / 1000} seconds to recharge.`,
    stat: () => `${RELAX_MS / 1000}s of spreading out`
});

/* ---- electric ball: charges up as it hits pegs, then discharges an arc that jumps from peg to peg ---- */
export const ZAP_COSTS: Costs = { evil: 25, goo: 100 };             // fixed price
export const ZAP_HITS = 8;                                          // peg hits for a full charge
export const ZAP_R = 60;                                            // how far the arc jumps from one peg to the next
export const ZAP_BRANCH = 2;                                        // each tagged peg passes the arc on to this many pegs at most
export const ZAP_MAX = 15;                                          // pegs tagged per discharge
export const ZAP_DELAY = 70;                                        // ms per jump, so the arc can be seen travelling
power('electric_ball', {
    required: [{ id: 'evil' }], act: COLORS.theme.electric, name: 'Electric Ball',
    costs: ZAP_COSTS,
    desc: `Fires an electric ball (it does not count towards your ball limit). Every peg it hits charges it up. After ${ZAP_HITS} hits it discharges: an arc jumps from that peg to the pegs nearby, and from those to more pegs, up to ${ZAP_MAX}. Every peg the arc touches counts as hit by the ball, and the electric ball collects the rewards. Then it charges up again.`,
    status: () => 'one at a time',
    stat: () => `discharges every ${ZAP_HITS} hits, up to ${ZAP_MAX} pegs`,
    use: game => game.zap.launch()
});

export const POWERS = Object.values(POWER_BY_ID);
for (const pw of POWERS) {
    for (const r of pw.required || []) if (!UPGRADE_BY_ID[r.id]) console.error(`Power "${pw.id}" requires "${r.id}", which does not exist`);
    for (const c in pw.costs) if (!isCurrency(c)) console.error(`Power "${pw.id}" costs an unknown currency "${c}"`);
    if (!pw.ms === !pw.use) console.error(`Power "${pw.id}" needs either ms/cd or use`);
}
