import type { IInputTarget } from '../engine/Input';
import type { Game } from '../game/Game';
import type { Peg, Point } from '../game/Types';
import type { SaveStore } from '../save/SaveStore';
import type { Ui } from './Ui';

/* =====================================================================
   BOARD CONTROLS: in edit mode tap to place / pick up a peg and drag a peg to move it; otherwise a tap launches
   ===================================================================== */
export class BoardControls implements IInputTarget<Peg> {
    game: Game;
    ui: Ui;
    store: SaveStore;
    constructor(game: Game, ui: Ui, store: SaveStore) {
        this.game = game;
        this.ui = ui;
        this.store = store;
    }
    // in edit mode a drag that starts on a peg moves it
    grab(w: Point): Peg | null { return this.game.editing ? this.game.pegs.at(w.x, w.y) ?? null : null; }
    dragTo(peg: Peg, w: Point): void { this.game.edit.dragPeg(peg, w.x, w.y); }
    drop(peg: Peg): void { this.game.edit.dropPeg(peg); this.store.save(); }

    tap(w: Point): void {
        const game = this.game, ui = this.ui;
        if (game.editing) {                  // edit mode: tap a peg to pick it up, tap anywhere else to place the selected type
            const peg = game.pegs.at(w.x, w.y);
            if (peg) {
                const back = game.edit.pickUp(peg);
                ui.toast(back ? `Peg picked up: ${back} back` : 'Peg picked up');
            } else {
                const why = game.edit.placePeg(ui.edit.selected, w.x, w.y);
                if (why) ui.toast(why, 2200);
            }
            ui.refresh();
            this.store.save();
            return;
        }
        ui.launch();                         // play mode: a tap anywhere on the board launches a ball
    }
}
