import { type Costs, type Currency, CUR_FIELD } from '../config/Currencies';
import type { Progress } from '../game/Progress';
import type { TempEffects } from '../game/TempEffects';
import type { Peg, PegType } from '../game/Types';
import { blastHits, LAB_FIRST, worldHeight } from '../upgrades/MoneyUpgrades';
import { PEG_KINDS, PEG_TYPES } from '../upgrades/PegKinds';
import { UPGRADES } from '../upgrades/Registry';
import { applyRenames, isPreEditMode, migrateEditMode, migrateLevels } from './Migrations';
import { num, SAVE_CODE, SAVE_TYPE, SAVE_VERSION, type SaveData } from './SaveFormat';

// what a save is made from (the Game fits)
export type SaveSource = {
    progress: Progress, temps: TempEffects, autoOn: boolean, labT: number,
    pegs: { list: readonly Pick<Peg, 'x' | 'y' | 'type' | 'left' | 'dmg' | 'paid' | 'free'>[] },
};

// a peg to put back on the board
export type LoadedPeg = { x: number, y: number, type: PegType, left: number, dmg: number, paid: Costs, free: boolean };

// what a save holds besides the progress it was loaded into
export type LoadedGame = { autoOn?: boolean, labT?: number, pegs: LoadedPeg[] };

export function encodeSave(g: SaveSource): SaveData {
    const p = g.progress;
    return {
        v: SAVE_VERSION, money: p.money, rp: p.rp, goo: p.goo, evil: p.evil, autoOn: g.autoOn, labT: g.labT, levels: p.levels, freePegs: p.freePegs,
        timers: g.temps.toSave(),            // temporary goo upgrades: [time left running, cooldown left] (ms)
        // [x, y, type, hits left (blast), damage, paid { currency: amount }, placed for free (1/0)]
        pegs: g.pegs.list.map(pg => [Math.round(pg.x * 10) / 10, Math.round(pg.y * 10) / 10, SAVE_CODE[pg.type] || 'b', pg.left || 0, Math.round(pg.dmg * 100) / 100, pg.paid, pg.free ? 1 : 0]),
    };
}

// loads balances, levels, free pegs and timers into p and temps (migrating older versions); returns the rest
export function decodeSave(d: SaveData, p: Progress, temps: TempEffects): LoadedGame {
    const out: LoadedGame = { pegs: [] };
    const pd = (v: unknown) => { const n = num(v); return n !== undefined ? Math.min(0.99, Math.max(0, n)) : 0; };   // saved peg damage
    for (const k of ['money', 'rp', 'goo', 'evil'] as const) { const n = num(d[k]); if (n !== undefined) p[k] = n; }   // goo is trimmed to the limit once the levels are loaded
    if (typeof d.autoOn === 'boolean') out.autoOn = d.autoOn;
    const labT = num(d.labT);
    if (labT !== undefined) out.labT = Math.min(Math.max(0, labT), LAB_FIRST);
    applyRenames(d);
    if (d.timers) temps.load(d.timers);
    if (d.levels) for (const u of UPGRADES) if (Number.isFinite(d.levels[u.id])) p.levels[u.id] = d.levels[u.id] | 0;
    const old = isPreEditMode(d);
    if (old) migrateEditMode(d, p);
    else if (d.freePegs) for (const t of PEG_TYPES) p.freePegs[t] = Math.max(0, d.freePegs[t] | 0);
    migrateLevels(d, p);
    p.goo = Math.min(p.goo, p.gooCap());
    const floor = worldHeight(p.L('deeper_world'));   // a peg centre may sit on the floor line
    for (const pt of Array.isArray(d.pegs) ? d.pegs : []) {
        if (!Array.isArray(pt) || !Number.isFinite(pt[0]) || !Number.isFinite(pt[1])) continue;
        const type: PegType = pt[2] === 'd' ? 'dual' : SAVE_TYPE[pt[2]] || 'basic';
        if (pt[1] > floor) {                 // below the floor (the board got shorter): back to be placed again for free
            if (type !== 'dual' || pt[3] > 0) p.freePegs[type]++;
            continue;
        }
        const left = type === 'dual' ? Math.min(blastHits(p.L('blast_peg_hits')), pt[3] | 0) : 0;   // blast pegs: hits left
        if (type === 'dual' && left <= 0) continue;
        const paid = old ? { ...PEG_KINDS[type].costs } : loadPaid(pt[5]);
        out.pegs.push({ x: pt[0], y: pt[1], type, left, dmg: pd(pt[4]), paid, free: !old && pt[6] === 1 });
    }
    return out;
}

// what a saved peg was paid: { currency: amount } (before v9 a plain amount of money)
export function loadPaid(v: unknown): Costs {
    const n = num(v);
    if (n !== undefined) return n > 0 ? { money: n } : {};
    const out: Costs = {};
    if (v && typeof v === 'object') {
        const o = v as Record<string, unknown>;
        for (const c of Object.keys(CUR_FIELD) as Currency[]) { const a = num(o[c]); if (a !== undefined && a > 0) out[c] = a; }
    }
    return out;
}
