import { COLORS } from '../../config/Colors';
import type { Balance } from '../../config/Currencies';
import type { Effects } from '../../engine/Effects';
import type { ContactPair } from '../../engine/Physics';
import { evFmt, fmt } from '../../util/Format';
import { evilDmg, evilYield } from '../../upgrades/GooEvilUpgrades';
import { gooballPegs, gooPerHit } from '../../upgrades/MoneyUpgrades';
import { DEAD_REST } from '../../upgrades/Powers';
import { EVIL_BASE, EVIL_KILL, GOO_PEG_MS } from '../../upgrades/ResearchUpgrades';
import type { Game } from '../Game';
import type { IHitContext } from '../pegs/IPegBehavior';
import { PEG_BEHAVIORS } from '../pegs/PegBehaviors';
import type { Ball, GameBody, Peg } from '../Types';

/* =====================================================================
   HITS: contacts -> peg hits. The shared rules (anti-farming, evil, goo) here; what each peg type pays in its behaviour
   ===================================================================== */
export class HitResolver implements IHitContext {
    game: Game;
    fx: Pick<Effects, 'burst' | 'float'>;
    constructor(game: Game) {
        this.game = game;
        const fx = game.effects;
        this.fx = { burst: (...a) => fx.burst(...a), float: (x, y, text, color, o = {}) => fx.float(x, y, text, color, { ...o, dim: true }) };
    }
    L(id: string): number { return this.game.L(id); }
    goldMul(ball: Ball): number { return this.game.ballSystem.goldMul(ball); }
    // everything a ball earns goes into its haul (ball.stash); the player only gets it when the ball lands in a bucket
    earn(ball: Ball, cur: Balance, v: number): void { ball.stash[cur] += v; }
    queueSplit(ball: Ball, peg: Peg): void { this.game.pendingSplit.push({ ball, peg }); }
    breakPeg(peg: Peg): void { peg.dead = true; this.game.pendingRemove.push(peg); }

    // Game rules for contacts, applied each step right after Matter sets up its contact pairs and before it resolves them:
    // a ghost ball's contact with a peg becomes a sensor (no push, but the hit is still reported), and Dead Balls takes the bounce out of every contact.
    contactRules(pairs: ContactPair<GameBody>[]): void {
        const g = this.game, dead = g.temps.running('dead_balls');
        for (const b of g.balls) b.inPeg = false;
        for (const pr of pairs) {
            const ball = pr.bodyA.ball || pr.bodyB.ball;
            if (!pr.isActive || !ball) continue;
            const onPeg = !!(pr.bodyA.peg || pr.bodyB.peg);
            if (onPeg) ball.inPeg = true;
            pr.isSensor = onPeg && ball.ghost;
            if (dead) pr.restitution = DEAD_REST;
        }
    }

    onContacts(pairs: ContactPair<GameBody>[]): void {
        const g = this.game;
        for (const pr of pairs) {
            let b = pr.bodyA, o = pr.bodyB;
            if (!b.ball) { b = pr.bodyB; o = pr.bodyA; }
            if (!b.ball) continue;
            if (g.temps.running('chaos_balls') && !pr.isSensor) b.ball.chaos = true;   // randomised right after this physics step (a ghost passing through a peg is no bounce)
            if (o.peg && this.hitPeg(b.ball, o.peg) && b.ball.zap) g.zap.charge(b.ball, o.peg);
        }
    }

    // a ball hits a peg and the peg pays out; arc = tagged by an electric arc (no anti-farming check, no charge)
    // returns false when the hit does not count
    hitPeg(ball: Ball, peg: Peg, arc = false): boolean {
        const g = this.game, fx = this.fx;
        if (peg.dead) return false;
        if (!arc) {
            if (ball.lastPeg === peg && g.simT - ball.lastT < 200) return false;   // no farming one peg while resting on it
            ball.lastPeg = peg; ball.lastT = g.simT;
        }
        peg.flash = 1;
        if (ball.goo && ++ball.gooHits >= gooballPegs(this.L('lasting_goo'))) ball.expired = true;   // gooballs burn out after enough pegs

        // evil: while the toggle is on, every hit damages the peg and yields evil (more evil the more damaged the peg is)
        if (g.evilOn) {
            const ey = evilYield(this.L('dark_harvest'));
            const ev = (EVIL_BASE + (1 - EVIL_BASE) * peg.dmg) * ey;
            this.earn(ball, 'evil', ev);
            peg.dmg += evilDmg(this.L('sturdy_pegs'));
            if (ev >= 0.25) fx.float(peg.x - 10, peg.y - 22, `+{evil}${evFmt(ev)}`, COLORS.theme.evil);
            if (peg.dmg >= 1) {                  // too much damage: the peg breaks and must be placed again
                peg.dmg = 1; peg.dead = true; peg.evilKill = true; g.pendingRemove.push(peg);
                const ek = EVIL_KILL * ey;
                this.earn(ball, 'evil', ek);
                fx.burst(peg.x, peg.y, COLORS.theme.evil, 24);
                fx.float(peg.x, peg.y - 34, `+{evil}${evFmt(ek)}`, COLORS.theme.evil, { big: true, life: 1100, always: true });
            }
        }

        // goo: a gooball coats pegs; any other ball that hits a coated peg produces Phlegm Goo
        const behavior = PEG_BEHAVIORS[peg.type];
        if (behavior.takesGoo) {
            if (ball.goo) peg.gooT = GOO_PEG_MS;
            else if (peg.gooT > 0) {
                const goo = gooPerHit(this.L('rich_phlegm'));
                this.earn(ball, 'goo', goo);
                fx.float(peg.x + 10, peg.y - 22, `+{goo}${fmt(goo)}`, COLORS.theme.goo);
            }
        }

        behavior.onHit(this, ball, peg);
        return true;
    }
}
