import { defineIn, type Upgrade } from './Types';
import { fmt, secs } from '../util/Format';
import { soft } from '../util/MathUtil';

/* ---- Money tab: paid in money (some also in research points or goo). Each upgrade's constants go right above it. ---- */
export const MONEY_MAX = 5;                                         // base max level of the normal money upgrades
export const CAP_STEP = 5;                                          // money upgrade max levels added per Upgrade Limit level

export const MONEY_UPGRADES: Upgrade[] = [];
const upgrade = defineIn(MONEY_UPGRADES);

export const bucketValue = (l: number) => 1 + l;
upgrade('bucket_value', {
    section: 'bucket',
    tab: 'money',
    name: 'Bucket Value', max: 10 * MONEY_MAX,
    costs: { money: { base: 5, growth: 1.3 } },
    desc: 'Increases the value of the buckets.',
    stat: l => `{money}${fmt(bucketValue(l))} per catch`
});

export const START_SLOTS = 3;                                       // peg slots before any Peg Slots upgrade
upgrade('peg_slots', {
    section: 'pegs',
    tab: 'money',
    name: 'Peg Slots', max: 0,
    required: [{ id: 'bucket_value', level: 2 }],
    costs: { money: { base: 5, growth: 1.2 } },
    desc: 'Increase the number of pegs you can have.',
    stat: l => `${START_SLOTS + l} slots`
});

upgrade('peg_value', {
    section: 'pegs',
    tab: 'money',
    name: 'Peg Value', max: MONEY_MAX,
    required: [{ id: 'peg_slots', level: 5 }],
    costs: { money: { base: 20, growth: 1.5 } },
    desc: 'Increases the added value of pegs.',
    stat: l => `{money}${fmt(1 + l)} per hit`
});

upgrade('extra_ball', {
    section: 'balls',
    tab: 'money',
    name: 'Extra Ball', max: MONEY_MAX,
    required: [{ id: "peg_value", level: 2 }],
    costs: { money: { base: 50, growth: 2.4 } },
    desc: 'Allows one more ball in play at the same time.',
    stat: l => `${1 + l} ball${l ? 's' : ''} at once`
});

upgrade('peg_power', {
    section: 'pegs',
    tab: 'money',
    name: 'Peg Power', max: MONEY_MAX,
    required: [{ id: 'peg_slots', level: 10 }],
    costs: { money: { base: 120, growth: 1.8 } },
    desc: 'Multiplies the value of every peg hit.',
    stat: l => `x${(1 + 0.5 * l).toFixed(1)}`
});

export const bucketW = (l: number) => soft(160, 280, 0.89, l);                // soft limit 280 (keeps 7 buckets plus gaps inside the board)
upgrade('wide_bucket', {
    section: 'bucket',
    tab: 'money',
    name: 'Wide Bucket', max: MONEY_MAX,
    required: [{ id: 'bucket_value', level: 8 }],
    costs: { money: { base: 120, growth: 1.9 } },
    desc: 'A wider bucket is easier to hit (with more buckets, the whole row gets wider).',
    stat: l => `${Math.round(bucketW(l))} wide`
});

export const LAB_FIRST = 10000, LAB_MIN = 50;                       // research lab: ms between ticks at level 1, and the limit it approaches (1/20 s)
export const labInterval = (l: number) => LAB_MIN + (LAB_FIRST - LAB_MIN) / l; // 10s, 5s, 3.3s ... each level helps less, never below LAB_MIN
upgrade('research_lab', {
    section: 'research',
    tab: 'money',
    name: 'Research Lab', max: MONEY_MAX,
    required: [
        { id: 'extra_ball' },
        { id: 'wide_bucket' },
        { id: 'peg_power' },
    ],
    costs: { money: { base: 1000, growth: 1.7 } },
    desc: 'Unlocks research points (hexagons). The lab gives research points on a timer; every level makes it tick faster, with diminishing returns.',
    stat: l => l ? `1 tick every ${secs(labInterval(l))}` : 'no research'
});

upgrade('research_batch', {
    section: 'research',
    tab: 'money',
    name: 'Research Batch', max: MONEY_MAX,
    required: [{ id: 'research_lab', level: 3 }],
    costs: { money: { base: 25000, growth: 3 } },
    desc: 'Every tick of the Research Lab gives more research points.',
    stat: l => `{research}${1 + l} per tick`
});

export const RP_PEG = 1;                                            // research points per research-peg hit
export const rpPerHit = (l: number) => RP_PEG * (1 + l);                      // Research Pegs Value: +RP_PEG per level
upgrade('research_pegs_value', {
    section: 'pegs',
    tab: 'money',
    name: 'Research Pegs Value', max: MONEY_MAX,
    required: [{ id: 'research_pegs' }],
    costs: { money: { base: 3000, growth: 1.9 } },
    desc: 'Research Peg\'s hits are worth more.',
    stat: l => `{research}${fmt(rpPerHit(l))} per hit`
});

/* ---- unlocked by research: the research only unlocks them (or switches its feature on), the levels here are the effect ---- */
upgrade('combo_chain', {
    section: 'pegs',
    tab: 'money',
    name: 'Combo Chain', max: MONEY_MAX,
    required: [{ id: 'combo_theory' }],
    costs: { money: { base: 400, growth: 1.7 }, research: { base: 5, growth: 1.5 } },
    desc: 'Each consecutive peg hit by the same ball is worth more.',
    stat: l => `+${5 * l}% per hit in a row`
});

// alchemy pegs charge from ALCH_MIN to their max value over ALCH_MS (dark yellow -> bright gold); a hit pays the value and empties them
export const ALCH_MS = 10000, ALCH_MIN = 1;
export const alchMax = (l: number) => 100 + 50 * l;                           // Alchemy Pegs Value: +50 max per level
upgrade('alchemy_pegs_value', {
    section: 'pegs',
    tab: 'money',
    name: 'Alchemy Pegs Value', max: MONEY_MAX,
    required: [{ id: 'alchemy' }],
    costs: { money: { base: 2500, growth: 1.9 }, research: { base: 8, growth: 1.5 } },
    desc: 'Alchemy pegs charge up to a higher value (same minimum, same time to charge).',
    stat: l => `up to {money}${fmt(alchMax(l))} per hit`
});

// dual peg: hits before it vanishes, reward multiplier
export const DUAL_HITS = 5, DUAL_MULT = 100;
// Blast Peg Hits: +1 hit per level
export const blastHits = (l: number) => DUAL_HITS + l;
upgrade('blast_peg_hits', {
    section: 'pegs',
    tab: 'money',
    name: 'Blast Peg Hits', max: MONEY_MAX,
    required: [{ id: 'blast_pegs' }],
    costs: { money: { base: 20000, growth: 2 }, goo: { base: 50, growth: 1.5 } },
    desc: 'Blast pegs take more hits before they are used up (new blast pegs and ones already placed).',
    stat: l => `${blastHits(l)} hits per blast peg`
});

// bounce: very slow growth, never reaches 90%
export const restitution = (l: number) => soft(0.5, 0.9, 0.96, l);
upgrade('bouncy_balls', {
    section: 'balls',
    tab: 'money',
    name: 'Bouncy Balls', max: 0,
    required: [{ id: 'elastic_balls' }],
    costs: { money: { base: 1200, growth: 1.9 }, goo: { base: 77, growth: 1.6 } },
    desc: 'Balls keep more energy when they bounce. Can be bought without end, but the gains keep shrinking and never quite reach 90%.',
    stat: l => `${(restitution(l) * 100).toFixed(1)}% bounce`
});

export const ballRadius = (l: number) => soft(6, 14, 0.93, l);                // soft limit 14
upgrade('fat_balls', {
    section: 'balls',
    tab: 'money',
    name: 'Fat Balls', max: MONEY_MAX,
    required: [{ id: 'ball_inflation' }],
    costs: { money: { base: 2000, growth: 1.9 } },
    desc: 'Bigger balls are harder to miss with.',
    stat: l => `radius ${ballRadius(l).toFixed(1)} (max 14)`
});

// Each level adds less height than the one before, but the sum never stops growing (a power below 1 has no asymptote).
// Level 8 still gives the same 1479 as the old linear formula.
export const worldHeight = (l: number) => Math.round(360 + 191 * l ** 0.85);
upgrade('deeper_world', {
    section: 'world',
    tab: 'money',
    name: 'Deeper World', max: 0,
    required: [{ id: 'world_size' }],
    costs: { money: { base: 20000, growth: 1.8 }, research: { base: 100, growth: 1.5 } },
    desc: 'Makes the board taller still: more room below the launcher for pegs. Every level adds a little less height than the last, but there is no limit.',
    stat: l => `${worldHeight(l)} tall`
});

export const autoInterval = (l: number) => 2000 * 0.85 ** (l - 1);      // ms between automatic drops
upgrade('faster_dropper', {
    section: 'balls',
    tab: 'money',
    name: 'Faster Dropper', max: 13,
    required: [{ id: 'auto_dropper' }],
    costs: { money: { base: 1000, growth: 1.6 }, research: { base: 10, growth: 1.5 } },
    desc: 'The Auto Dropper drops balls faster.',
    stat: l => `1 ball every ${(autoInterval(1 + l) / 1000).toFixed(2)}s`
});

export const bucketCount = (l: number) => l >= 20 ? 7 : l >= 15 ? 6 : l >= 10 ? 5 : l >= 7 ? 4 : l >= 4 ? 3 : l >= 1 ? 2 : 1;
export const BUCKET_GAP = 12;                                       // empty space between neighbouring buckets (a ball falling in the gap is lost)
export const midMult = (l: number) => 1 + 0.5 * l;                            // value multiplier of the middle bucket
export const edgeMult = (l: number) => 1 / (1 + 0.1 * l);                     // value multiplier of the outermost buckets
upgrade('extra_buckets', {
    section: 'bucket',
    tab: 'money',
    required: [{ id: 'more_buckets' }], name: 'Extra Buckets', max: 0,
    costs: { money: { base: 3000, growth: 1.25 } },
    desc: 'More buckets at the bottom: 2 at level 1, 3 at level 4, then 4, 5, 6 and 7 (at levels 7, 10, 15 and 20). The middle ones pay more and the outer ones less, and every level widens the gap. Balls that fall between buckets are lost.',
    stat: l => `${bucketCount(l)} bucket${bucketCount(l) > 1 ? 's' : ''}, middle x${midMult(l).toFixed(1)}, edges x${edgeMult(l).toFixed(2)}`
});

export const GOLD_CHANCE = 0.05;                                     // chance that a launched ball is a gold ball (once researched)
export const goldMult = (l: number) => l <= 0 ? 1 : 2 + 0.25 * (l - 1);       // money multiplier of gold balls: x2 at level 1, slowly rising
upgrade('gold_ball_value', {
    section: 'balls',
    tab: 'money',
    required: [{ id: 'gold_balls' }], name: 'Gold Ball Value', max: 11,
    costs: { money: { base: 5000, growth: 1.5 } },
    desc: 'Gold balls multiply the money they earn even more.',
    stat: l => `x${goldMult(1 + l).toFixed(2)} {money}`
});

export const GOO_MAX = 10;                                          // research levels of Phlegm Goo
export const gooChance = (l: number) => l <= 0 ? 0 : 0.01 + 0.04 * (1 - 0.75 ** (l - 1)) / (1 - 0.75 ** (GOO_MAX - 1));   // 1% at level 1, 5% at max level, diminishing steps
upgrade('more_gooballs', {
    section: 'goo',
    tab: 'money',
    required: [{ id: 'phlegm_goo' }], name: 'More Gooballs', max: GOO_MAX - 1,
    costs: { money: { base: 20000, growth: 1.6 }, goo: { base: 100, growth: 1.6 } },
    desc: 'More of the launched balls are gooballs, with diminishing returns.',
    stat: l => `${(gooChance(1 + l) * 100).toFixed(1)}% gooball chance`
});

export const gooballPegs = (l: number) => 10 + 2 * l;                         // a gooball vanishes after touching this many pegs (Lasting Goo: +2 per level)
upgrade('lasting_goo', {
    section: 'goo',
    tab: 'money',
    required: [{ id: 'phlegm_goo' }], name: 'Lasting Goo', max: 0,
    costs: { money: { base: 50000, growth: 4 }, goo: { base: 250, growth: 1.6 } },
    desc: 'Gooballs touch more pegs before they burn out, so they coat more pegs.',
    stat: l => `${gooballPegs(l)} pegs per gooball`
});

export const gooPerHit = (l: number) => 1 + l;                                // Phlegm Goo per (non-goo) ball hit on a goo peg (Rich Phlegm: +1 per level)
upgrade('rich_phlegm', {
    section: 'goo',
    tab: 'money',
    name: 'Rich Phlegm', max: 0,
    required: [{ id: 'phlegm_goo' }],
    costs: { money: { base: 100000, growth: 5 }, goo: { base: 33, growth: 2 } },
    desc: 'Every hit on a goo-coated peg produces more Phlegm Goo.',
    stat: l => `{goo}${gooPerHit(l)} per hit`
});

upgrade('higher_limit', {   // uncapped: its own maximum is not raised by Upgrade Limit (otherwise every level would raise it further)
    section: 'world',
    tab: 'money',
    required: [{ id: 'upgrade_limit' }], uncapped: true, name: 'Higher Limit', max: 15,
    costs: { money: { base: 50000, growth: 3.7 } },
    desc: `Raises the maximum level of every money upgrade that has one by another ${CAP_STEP}.`,
    stat: l => `money upgrades +${CAP_STEP * l} levels`
});
