import { COLORS } from './Colors';
import { fmt } from '../util/Format';

// the currencies costs can use
export type Currency = 'money' | 'research' | 'goo' | 'evil';
// where a currency's balance lives in Progress and in a ball's haul (research points are `rp` inside the code)
export type Balance = 'money' | 'rp' | 'goo' | 'evil';
// a price: { currency: amount }
export type Costs = Partial<Record<Currency, number>>;

// card colour per currency (a card takes the colour of the first currency it costs)
export const RES_COL: Record<Currency, string> = { money: COLORS.ui.strong, research: COLORS.theme.research, goo: COLORS.theme.goo, evil: COLORS.theme.evil };
export const CUR_FIELD: Record<Currency, Balance> = { money: 'money', research: 'rp', goo: 'goo', evil: 'evil' };
export const CURRENCIES = Object.keys(CUR_FIELD) as Currency[];
// a currency's icon inside a text: {money}, {research}, {goo}, {evil} (the page and the board draw it as the icon)
export const sym = (c: Currency) => `{${c}}`;
// costs as text with icons (toasts): { money: 10, evil: 20 } -> '{money}10 + {evil}20'
export const costText = (c: Costs) => entries(c).map(([cur, a]) => `${sym(cur)}${fmt(a)}`).join(' + ');

// Object.entries keeping the key and value types (Object.entries widens keys to string)
export const entries = <K extends string, V>(o: Partial<Record<K, V>>) => Object.entries(o) as [K, V][];
export const isCurrency = (c: string): c is Currency => c in CUR_FIELD;
