// a short message in the hint line under the board, for a while
export class Toast {
    text: string;
    until: number;
    constructor() {
        this.text = '';
        this.until = 0;
    }
    show(text: string, ms = 1600): void { this.text = text; this.until = performance.now() + ms; }
    // the message while it lasts, else null
    current(): string | null { return performance.now() < this.until ? this.text : null; }
}
