import { COLORS } from '../config/Colors';
import { type Balance, costText, type Currency } from '../config/Currencies';
import type { Camera } from '../engine/Camera';
import { DEBUG } from '../engine/Settings';
import type { Game } from '../game/Game';
import type { GameRenderer } from '../render/GameRenderer';
import type { SaveStore } from '../save/SaveStore';
import { evFmt, fmt } from '../util/Format';
import { PEG_KINDS } from '../upgrades/PegKinds';
import { EditPanel } from './EditPanel';
import { loadPrefs, type Prefs } from './Prefs';
import { PowersView } from './PowersView';
import { type Mode, SettingsView } from './SettingsView';
import { ShopView } from './ShopView';
import { SystemView } from './SystemView';
import { Toast } from './Toast';
import { byId, CUR_ICON, iconHtml, type Screen, SCREENS, setHtml, setText } from './UiHelpers';

const SCREEN_LIST = Object.keys(SCREENS) as Screen[];

/* =====================================================================
   UI: HUD, buttons, the hint line, keyboard, and which screen (shop, research, powers, settings, system) is over the board
   ===================================================================== */
export class Ui {
    game: Game;
    camera: Camera;
    store: SaveStore;
    d: Record<string, HTMLElement>;
    prefs: Prefs;
    edit: EditPanel;
    shop: ShopView;
    research: ShopView;
    powers: PowersView;
    settings: SettingsView;
    system: SystemView;
    toaster: Toast;
    hudH: number;
    screen: Screen | null;
    padObserver: ResizeObserver | null;
    constructor(game: Game, camera: Camera, store: SaveStore, renderer: GameRenderer) {
        this.game = game;
        this.camera = camera;
        this.store = store;
        this.d = {};
        for (const id of ['app', 'hud', 'bar', 'hint', 'btns', 'settingsBtn', 'editBtn', 'upBtn', 'researchBtn', 'powersBtn', 'doneBtn', ...Object.values(SCREENS),
            'money', 'rpBox', 'rpNum', 'gooBox', 'gooNum', 'evilBox', 'evilNum', 'stBalls', 'stPegs']) this.d[id] = byId(id);
        // the counters' icons
        for (const [box, c] of [['moneyBox', 'money'], ['rpBox', 'research'], ['gooBox', 'goo'], ['evilBox', 'evil']] as [string, Currency][]) byId(box).insertAdjacentHTML('afterbegin', CUR_ICON[c]);
        this.prefs = loadPrefs();
        this.edit = new EditPanel(game, renderer);
        this.shop = new ShopView(game, 'money', 'list', () => this.refresh());
        this.research = new ShopView(game, 'research', 'resList', () => this.refresh());
        // after launching a power: get the screen out of the way to watch it (a setting)
        this.powers = new PowersView(game, () => { if (this.prefs.closeOnPower) this.showScreen(null); else this.refresh(); });
        this.settings = new SettingsView(this.modeList(), () => this.showScreen('system'));
        this.system = new SystemView(store, this.prefs);
        this.toaster = new Toast();
        this.hudH = -1;
        this.screen = null;                  // the open screen: 'shop', 'research', 'powers', 'settings', 'system' or null

        const d = this.d;
        d.upBtn.addEventListener('click', () => this.toggleScreen('shop'));
        d.researchBtn.addEventListener('click', () => this.toggleScreen('research'));
        // settings, or system opened from it: the button closes either
        d.settingsBtn.addEventListener('click', () => this.showScreen(this.settingsOpen || this.systemOpen ? null : 'settings'));
        d.powersBtn.addEventListener('click', () => this.toggleScreen('powers'));
        d.editBtn.addEventListener('click', () => this.toggleEdit());
        d.doneBtn.addEventListener('click', () => this.toggleEdit());
        if (DEBUG) this.debugResources();
        window.addEventListener('keydown', e => {
            if (e.key === 'Escape') { if (game.editing) this.toggleEdit(); else this.showScreen(null); }
            else if ((e.key === 'e' || e.key === 'E') && !e.repeat) this.setEvil(!game.evilOn);
            else if (e.code === 'Space' && !e.repeat && !game.editing) { e.preventDefault(); this.launch(); }
        });

        // reading offsetHeight every frame forces a layout; only re-measure when the HUD or button bar actually change size
        this.padObserver = window.ResizeObserver ? new ResizeObserver(() => { this.measurePads(); camera.clamp(); }) : null;
        if (this.padObserver) { this.padObserver.observe(d.hud); this.padObserver.observe(d.bar); }
    }

    get shopOpen(): boolean { return this.screen === 'shop'; }
    get researchOpen(): boolean { return this.screen === 'research'; }
    get powersOpen(): boolean { return this.screen === 'powers'; }
    get settingsOpen(): boolean { return this.screen === 'settings'; }
    get systemOpen(): boolean { return this.screen === 'system'; }
    get panelOpen(): boolean { return !!this.screen && !this.settingsOpen; }   // a screen covers the board (the settings panel only covers half of it)

    // the switches in the settings panel
    modeList(): Mode[] {
        const game = this.game;
        return [{
            label: 'Auto launch balls', color: COLORS.ui.autoLaunch,
            available: () => game.L('auto_dropper') > 0,
            on: () => game.autoOn,
            toggle: () => { game.autoOn = !game.autoOn; this.refresh(); this.store.save(); },
        }, {
            label: 'Evil damage (E)', color: COLORS.theme.evil,
            available: () => game.L('evil') > 0,
            on: () => game.evilOn,
            toggle: () => this.setEvil(!game.evilOn),
        }];
    }

    // ?debug: tapping a resource counter at the top gives 10% more of it (1 when there is none; goo stays within its tank)
    debugResources(): void {
        const p = this.game.progress;
        for (const [box, cur] of [['moneyBox', 'money'], ['rpBox', 'rp'], ['gooBox', 'goo'], ['evilBox', 'evil']] as [string, Balance][]) {
            const el = byId(box);
            el.style.pointerEvents = 'auto';
            el.style.cursor = 'pointer';
            el.addEventListener('click', () => {
                p[cur] = p[cur] > 0 ? p[cur] * 1.1 : 1;
                if (cur === 'goo') p.goo = Math.min(p.goo, p.gooCap());
                this.toast(`debug: ${cur} x1.1`, 800);
                this.refresh();
            });
        }
    }

    // one screen at a time over the board (null closes it); the screens stop above the button bar
    showScreen(name: Screen | null): void {
        const d = this.d;
        this.screen = name;
        for (const sc of SCREEN_LIST) {
            const el = d[SCREENS[sc]], on = sc === name;
            el.classList.toggle('open', on);
            el.setAttribute('aria-hidden', on ? 'false' : 'true');
        }
        d.app.classList.toggle('ov', !!name);
        if (name) d.app.style.setProperty('--barH', `${d.bar.offsetHeight}px`);
        if (name === 'system') this.system.clearMsg();
        this.refresh();
    }
    toggleScreen(name: Screen): void { this.showScreen(this.screen === name ? null : name); }

    launch(): void {
        if (this.game.ballSystem.launch()) return;
        this.toast(this.game.ballSystem.maxBalls() === 1 ? 'A ball is already in play' : 'All balls are in play');
    }
    toast(t: string, ms = 1600): void { this.toaster.show(t, ms); }

    // edit mode on/off: the bottom bar swaps its buttons for the peg palette, and the game stands still meanwhile
    toggleEdit(): void {
        const game = this.game, d = this.d;
        if (game.editing) {
            game.edit.exit();
            this.edit.showTip(null);
            d.app.classList.remove('edit');
            this.store.save();
        } else {
            this.showScreen(null);
            const refund = game.edit.enter();
            if (Object.keys(refund).length) this.toast(`Special ball cleared: +${costText(refund)}`, 2400);
            d.app.classList.add('edit');
        }
        this.refresh();
    }
    setEvil(on: boolean): void {
        this.game.evilOn = !!on && this.game.L('evil') > 0;
        this.d.app.classList.toggle('evil', this.game.evilOn);
        this.refresh();
    }

    // how much of the screen the HUD and the button bar cover (the camera keeps the board between them)
    measurePads(): void {
        const d = this.d, h = d.hud.offsetHeight;
        if (h !== this.hudH) { this.hudH = h; d.app.style.setProperty('--hudH', `${h}px`); }   // the shop starts right below the HUD
        this.camera.padTop = h - 6;
        if (!d.app.classList.contains('ov')) this.camera.padBot = d.bar.offsetHeight;      // measured only while the bar is in its normal state
    }

    refresh(): void {
        const game = this.game, p = game.progress, pegs = game.pegs, d = this.d;
        game.uiDirty = false;

        setText(d.money, fmt(Math.floor(p.money)));
        const hasRp = p.L('research_lab') > 0, hasGoo = p.L('phlegm_goo') > 0, hasEvil = p.L('evil') > 0;
        d.rpBox.classList.toggle('on', hasRp);
        if (hasRp) setText(d.rpNum, fmt(Math.floor(p.rp * 10) / 10));
        d.gooBox.classList.toggle('on', hasGoo);
        if (hasGoo) setText(d.gooNum, fmt(Math.floor(p.goo)));
        if (!hasEvil && game.evilOn) this.setEvil(false);
        d.evilBox.classList.toggle('on', hasEvil);
        if (hasEvil) setText(d.evilNum, evFmt(Math.floor(p.evil * 100) / 100));
        // the round buttons keep their slot while locked (an empty translucent circle)
        this.settings.refresh();
        d.settingsBtn.classList.toggle('on', this.settingsOpen || this.systemOpen);
        d.powersBtn.classList.toggle('locked', !hasGoo);
        d.powersBtn.classList.toggle('on', this.powersOpen);
        d.researchBtn.classList.toggle('locked', !hasRp);
        d.researchBtn.classList.toggle('on', this.researchOpen);
        setText(d.stBalls, `${fmt(game.ballSystem.load())}/${game.ballSystem.maxBalls()}`);
        setText(d.stPegs, `${pegs.used()}/${p.slots()}`);   // pegs on the board / peg slots

        // a dot on a button when something behind it can be bought or launched
        const canBuy = this.shop.refresh(), canResearch = this.research.refresh(), canUse = this.powers.refresh();
        d.powersBtn.classList.toggle('alert', canUse && !this.powersOpen);
        d.researchBtn.classList.toggle('alert', hasRp && canResearch && !this.researchOpen);
        const open = this.shopOpen;
        d.upBtn.classList.toggle('alert', canBuy && !open);
        d.upBtn.classList.toggle('on', open);

        let h = '', pulse = false;
        const freeSlots = p.slots() - pegs.used(), canPay = p.has(PEG_KINDS.basic.costs) || Object.values<number>(p.freePegs).some(n => n > 0);
        const toast = this.toaster.current();
        if (toast !== null) h = toast;
        else if (game.editing) h = 'Tap: place · tap a peg: remove · drag: move';
        else if (pegs.list.length === 0) {
            h = canPay ? 'Tap ✎ to place your first peg' : 'Tap to launch when the cannon is over the bucket';
            pulse = true;
        } else if (freeSlots > 0 && canPay) { h = `${freeSlots} free slot${freeSlots > 1 ? 's' : ''}: tap ✎ to place pegs`; pulse = true; }
        setHtml(d.hint, iconHtml(h));                       // toasts can name prices: {money}150
        d.hint.classList.toggle('pulse', pulse);
        if (game.editing) this.edit.refresh();
    }
}
