import { App } from './App';
import { applyCssColors } from './config/Colors';
import './styles/game.css';

/* Neon Pegs entry point: bundled by esbuild into dist/game.js and dist/game.css (one classic script, so opening index.html from disk still works). */
applyCssColors(document.documentElement);   // the CSS reads its colours from the palette
new App().start();
