import type { Game } from '../game/Game';
import { decodeSave, encodeSave } from './SaveCodec';
import { parseSave, SAVE_KEY, type SaveData } from './SaveFormat';

/* =====================================================================
   SAVE / LOAD: localStorage and the page (the format is in SaveCodec)
   ===================================================================== */
export class SaveStore {
    game: Game;
    resetting: boolean;
    constructor(game: Game) {
        this.game = game;
        this.resetting = false;              // no more saving once a reset is under way
    }
    autosave(): void {
        setInterval(() => this.save(), 5000);
        document.addEventListener('visibilitychange', () => { if (document.hidden) this.save(); });
        window.addEventListener('pagehide', () => this.save());
    }
    reset(): void {
        this.resetting = true;
        try { localStorage.removeItem(SAVE_KEY); } catch { }
        location.reload();
    }
    // the current progress as text (the same JSON that is kept in localStorage), for the settings screen's export
    exportText(): string {
        this.save();
        try { return localStorage.getItem(SAVE_KEY) || ''; } catch { return ''; }
    }
    // replaces the current progress with a save from text and reloads the page; false when the text is not a valid save
    import(text: string): boolean {
        const d = parseSave(text);
        if (!d) return false;
        try { localStorage.setItem(SAVE_KEY, JSON.stringify(d)); } catch { return false; }
        this.resetting = true;               // the page is about to reload: no autosave may overwrite the imported save
        location.reload();
        return true;
    }
    save(): void {
        if (this.resetting) return;
        try { localStorage.setItem(SAVE_KEY, JSON.stringify(encodeSave(this.game))); } catch { }
    }
    load(): void {
        const g = this.game;
        try {
            const raw = localStorage.getItem(SAVE_KEY);
            if (!raw) return;
            const s = decodeSave(JSON.parse(raw) as SaveData, g.progress, g.temps);
            if (s.autoOn !== undefined) g.autoOn = s.autoOn;
            if (s.labT !== undefined) g.labT = s.labT;
            g.growWorld();
            for (const pg of s.pegs) g.pegs.add(pg.x, pg.y, pg.type, pg.left, pg.dmg, pg.paid, pg.free);
        } catch { }
    }
}
