import { defineIn, type Upgrade } from './Types';
import { EVIL_DMG } from './ResearchUpgrades';

/* ---- paid in Phlegm Goo and Evil (shown in the Money tab) ---- */
export const GOO_EVIL_UPGRADES: Upgrade[] = [];
const upgrade = defineIn(GOO_EVIL_UPGRADES);

export const GOO_BASE_CAP = 100, GOO_CAP_GROWTH = 1.35;             // the most Phlegm Goo you can hold: starts at 100, x1.35 per Goo Tank level (rounded to 10 up to Lv 4, then to 100)
export const gooCap = (l: number) => { const step = l > 4 ? 100 : 10; return Math.round(GOO_BASE_CAP * GOO_CAP_GROWTH ** l / step) * step; };
upgrade('goo_tank', {
    section: 'goo',
    required: [{ id: 'phlegm_goo' }], name: 'Goo Tank', tab: 'money', max: 0,
    costs: { goo: { fn: l => gooCap(l) / 2 } },
    desc: `Raises the most Phlegm Goo you can hold by ${Math.round((GOO_CAP_GROWTH - 1) * 100)}%. It always costs half a tank: half your current limit.`,
    stat: l => `holds up to {goo}${gooCap(l)}`
});

export const evilDmg = (l: number) => EVIL_DMG * (0.1 + 0.9 * 0.9778 ** l);   // Sturdy Pegs: soft limit, damage keeps shrinking but never goes below 10% of the base
upgrade('sturdy_pegs', {
    section: 'evil',
    required: [{ id: 'evil' }], name: 'Sturdy Pegs', tab: 'money', max: 0,
    costs: { evil: { base: 25, growth: 1.6 } },
    desc: 'Pegs take less damage from each hit while Evil is on, so they last longer. Can be bought without end, but each level helps less and damage never drops below 10% of the original.',
    stat: l => `${(evilDmg(l) * 100).toFixed(2)}% damage per hit (${Math.round(evilDmg(l) / EVIL_DMG * 100)}% of base)`
});

export const evilRegen = (l: number) => 0.02 * (1 + 0.6 * l);                 // damage healed per second while evil is off
upgrade('fast_healing', {   // uncapped: Upgrade Limit only raises the upgrades paid in money
    section: 'evil',
    required: [{ id: 'evil' }], name: 'Fast Healing', tab: 'money', max: 10, uncapped: true,
    costs: { evil: { base: 25, growth: 1.6 } },
    desc: 'Damaged pegs heal faster while Evil is off.',
    stat: l => `${(evilRegen(l) * 100).toFixed(1)}% healed per second`
});

export const evilYield = (l: number) => 1 + 0.25 * l;                         // multiplier on all evil gained
upgrade('dark_harvest', {
    section: 'evil',
    required: [{ id: 'evil' }], name: 'Dark Harvest', tab: 'money', max: 10, uncapped: true,
    costs: { evil: { base: 50, growth: 1.7 } },
    desc: 'Every hit and every destroyed peg yields more Evil.',
    stat: l => `x${evilYield(l).toFixed(2)} {evil}`
});
