import { COLORS } from '../config/Colors';
import { parseSave } from '../save/SaveFormat';
import type { SaveStore } from '../save/SaveStore';
import { makeSwitch, setSwitch, settingRow } from './Cards';
import { Fullscreen } from './Fullscreen';
import { type Prefs, savePrefs } from './Prefs';
import { byId, child, setText } from './UiHelpers';

/* =====================================================================
   SYSTEM: slides up like the shop and uses the same cards; one row per setting (opened from the settings panel)
   ===================================================================== */
export class SystemView {
    store: SaveStore;
    prefs: Prefs;
    list: HTMLElement;
    msg: HTMLElement;
    fileInput: HTMLInputElement;
    msgT: number | undefined;
    fullscreen: Fullscreen;
    constructor(store: SaveStore, prefs: Prefs) {
        this.store = store;
        this.prefs = prefs;
        this.list = byId('sysList');
        this.msg = byId('sysMsg');

        // auto fullscreen: a switch on the right of the card; turning it on goes fullscreen right away
        this.fullscreen = new Fullscreen(() => prefs.autoFullscreen);
        const fsOk = this.fullscreen.supported;
        const fsCard = settingRow(this.list, COLORS.system.fullscreen, 'Auto fullscreen', fsOk
            ? 'Any tap goes back to fullscreen when you are not in it (hides the browser bars).'
            : 'This browser does not allow fullscreen.', []).el;
        fsCard.classList.add('sw');
        const fs = makeSwitch('Auto fullscreen');
        fs.disabled = !fsOk;
        child(fsCard, '.acts').append(fs);
        this.fullscreen.skip = fs;               // turning it off must not go fullscreen on that same tap
        setSwitch(fs, fsOk && prefs.autoFullscreen);
        fs.addEventListener('click', () => {
            prefs.autoFullscreen = !prefs.autoFullscreen;
            savePrefs(prefs);
            setSwitch(fs, prefs.autoFullscreen);
            if (prefs.autoFullscreen) this.fullscreen.enter();
        });

        const pow = this.row(COLORS.system.powers, 'Powers', 'Close the Powers screen after launching a power, so you can watch it work.',
            [['b', '', () => { prefs.closeOnPower = !prefs.closeOnPower; savePrefs(prefs); powUpdate(); }]]).b;
        const powUpdate = () => setText(child(pow, '.bc'), prefs.closeOnPower ? 'CLOSE AFTER LAUNCH: ON' : 'CLOSE AFTER LAUNCH: OFF');
        powUpdate();

        this.row(COLORS.system.exportSave, 'Export save', 'Download your progress as a file, or copy it as text, to keep it safe or move it to another device.', [
            ['file', 'DOWNLOAD', () => this.exportFile()],
            ['copy', 'COPY', () => this.exportCopy()],
        ]);
        this.row(COLORS.system.importSave, 'Import save', 'Replace your current progress with a saved file or with copied text.', [
            ['file', 'FROM FILE', () => this.fileInput.click()],
            ['paste', 'PASTE', () => this.importPaste()],
        ]);
        this.row(COLORS.system.reset, 'Reset game data', 'Erase all progress and start over.', [
            ['reset', 'RESET', () => { if (confirm('Erase all progress and start over?')) store.reset(); }],
        ]);

        // the hidden file picker behind "FROM FILE"
        this.fileInput = document.createElement('input');
        this.fileInput.type = 'file';
        this.fileInput.accept = '.json,.txt,application/json,text/plain';
        this.fileInput.addEventListener('change', () => {
            const file = this.fileInput.files?.[0];
            this.fileInput.value = '';           // so picking the same file again still fires
            if (file) file.text().then(t => this.importText(t), () => this.setMsg('Could not read that file', true));
        });
    }

    // a setting card in this screen; returns its buttons by id
    row(color: string, name: string, desc: string, buttons: [string, string, () => void][]): Record<string, HTMLButtonElement> {
        return settingRow(this.list, color, name, desc, buttons).btns;
    }

    // feedback line at the top of the system screen (the hint under the board is hidden while a screen is open)
    setMsg(text: string, err = false): void {
        const m = this.msg;
        m.textContent = text;
        m.classList.toggle('err', err);
        clearTimeout(this.msgT);
        this.msgT = setTimeout(() => { m.textContent = ''; }, 5000);
    }
    clearMsg(): void { this.msg.textContent = ''; }

    exportFile(): void {
        const text = this.store.exportText();
        if (!text) { this.setMsg('Nothing to export', true); return; }
        const a = document.createElement('a');
        a.href = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
        a.download = `neonpegs-save-${new Date().toISOString().slice(0, 10)}.json`;
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(() => URL.revokeObjectURL(a.href), 10000);
        this.setMsg('Save file downloaded');
    }
    exportCopy(): void {
        const text = this.store.exportText();
        if (!text) { this.setMsg('Nothing to export', true); return; }
        const fallback = () => window.prompt('Copy your save (Ctrl+C):', text);   // no clipboard access: show the text to copy by hand
        if (navigator.clipboard?.writeText) navigator.clipboard.writeText(text).then(() => this.setMsg('Save copied to the clipboard'), fallback);
        else fallback();
    }
    importPaste(): void {
        const go = (t: string | null) => t ? this.importText(t) : this.setMsg('Nothing to import', true);
        const ask = () => go(window.prompt('Paste your save here:'));
        if (navigator.clipboard?.readText) navigator.clipboard.readText().then(go, ask);
        else ask();
    }
    // checks the text, asks before replacing the progress, then the page reloads with the new save
    importText(text: string): void {
        const t = String(text).trim();
        if (!parseSave(t)) { this.setMsg('That is not a valid Neon Pegs save', true); return; }
        if (!confirm('Replace your current progress with this save?')) return;
        if (!this.store.import(t)) this.setMsg('Could not store the save', true);
    }
}
