import { POWER_BY_ID, POWERS } from '../upgrades/Powers';

export type TimerState = { t: number, cd: number };
// a power button's state: running / recharging ({ active, s }), the electric ball's charge ({ active, text }), or ready (null)
export type Timer = { active: boolean, s?: number, text?: string } | null;
export const tmr = (s: TimerState): Timer => s.t > 0 ? { active: true, s: Math.ceil(s.t / 1000) } : s.cd > 0 ? { active: false, s: Math.ceil(s.cd / 1000) } : null;

/* =====================================================================
   TIMED POWERS (the goo ones and the repulsion field): ms left running (t) and recharging (cd)
   ===================================================================== */
export class TempEffects {
    s: Record<string, TimerState>;
    constructor() {
        this.s = {};
        for (const pw of POWERS) if (pw.ms) this.s[pw.id] = { t: 0, cd: 0 };
    }
    running(id: string): boolean { return this.s[id].t > 0; }
    start(id: string): void { this.s[id].t = POWER_BY_ID[id].ms ?? 0; }
    timer(id: string): Timer { return this.s[id] ? tmr(this.s[id]) : null; }   // { active, s } while running or cooling down; null for the others
    tick(dt: number): void {                 // run, then recharge
        for (const id in this.s) {
            const s = this.s[id];
            if (s.t > 0) { s.t -= dt; if (s.t <= 0) { s.t = 0; s.cd = POWER_BY_ID[id].cd ?? 0; } }
            else if (s.cd > 0) s.cd = Math.max(0, s.cd - dt);
        }
    }
    toSave(): Record<string, [number, number]> { return Object.fromEntries(Object.keys(this.s).map(id => [id, [this.s[id].t, this.s[id].cd]])); }
    // no balls survive a reload, so an effect that was still running is not resumed: its time left plus the full cooldown is owed instead
    load(timers: Record<string, unknown>): void {
        for (const id in this.s) {
            const t = timers[id];
            if (!Array.isArray(t)) continue;
            const run = Number.isFinite(t[0]) ? Math.max(0, t[0]) : 0, left = Number.isFinite(t[1]) ? Math.max(0, t[1]) : 0;
            this.s[id].cd = Math.min(run > 0 ? run + (POWER_BY_ID[id].cd ?? 0) : left, 600000);
        }
    }
}
